-- ===== دليل شركاء النجاح: بيانات قابلة للتعديل من لوحة التحكم =====
-- شغّله مرة واحدة في Supabase SQL Editor (آمن للإعادة؛ لا يكرر البيانات المزروعة).

create table if not exists guide_orgs (
  id text primary key,                 -- o1, o2 ...
  name text not null,
  logo text,                           -- مسار الشعار (logos/xxx.png) أو رابط
  sort int not null default 0,
  hidden boolean not null default false,
  created_at timestamptz not null default now()
);
create table if not exists guide_services (
  id int generated by default as identity primary key,
  org text not null references guide_orgs(id) on update cascade on delete cascade,
  title text not null,
  descr text,
  link text,                           -- رابط الاستفادة (مع https://)
  raw text,                            -- النص الأصلي للرابط إن وُجد
  tags text[] not null default '{}',
  cats text[] not null default '{}',   -- fund, invest, mentor, incub, train, prod, tech, space, market, compete, ip
  note text,
  sort int not null default 0,
  hidden boolean not null default false,
  updated_at timestamptz not null default now()
);
alter table guide_orgs enable row level security;
alter table guide_services enable row level security;
drop policy if exists "admin all guide orgs" on guide_orgs;
create policy "admin all guide orgs" on guide_orgs for all to authenticated using (is_admin_or_reviewer()) with check (is_admin_or_reviewer());
drop policy if exists "admin all guide services" on guide_services;
create policy "admin all guide services" on guide_services for all to authenticated using (is_admin_or_reviewer()) with check (is_admin_or_reviewer());

-- القراءة العامة للدليل: غير المخفي فقط
create or replace function guide_get() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'orgs', coalesce((select json_agg(json_build_object('id',o.id,'name',o.name,'logo',o.logo) order by o.sort, o.created_at, o.id) from guide_orgs o where not o.hidden),'[]'::json),
    'services', coalesce((select json_agg(json_build_object('id',s.id,'org',s.org,'title',s.title,'desc',s.descr,'link',s.link,'raw',s.raw,'tags',s.tags,'cats',s.cats,'note',s.note) order by s.sort, s.id)
                 from guide_services s join guide_orgs o on o.id=s.org where not s.hidden and not o.hidden),'[]'::json)
  );
$$;
grant execute on function guide_get() to anon, authenticated;

-- بذر البيانات الحالية (مرة واحدة فقط إذا كان الجدول فارغًا)
do $seed$ begin
if not exists (select 1 from guide_orgs) then
perform setval(pg_get_serial_sequence('guide_services','id'), (select max(id) from guide_services));
end if;
end $seed$;
