insert into guide_services (id,org,title,descr,link,raw,tags,cats,note,sort) overriding system value values
  (1,$q$o1$q$,$q$مختبر المنتجات الأولية – MVP Lab$q$,$q$يهدف البرنامج إلى دعم المبتكرين ورواد الأعمال في تحويل أفكارهم التقنية إلى منتجات أولية قابلة للاختبار والتحقق من جدواها في السوق. ويستهدف أصحاب المشاريع التقنية الذين يعملون على تطوير منتج قابل للتطبيق التجاري، أو لديهم نموذج أولي ويرغبون في استكمال تطويره وتأسيس شركة ناشئة. وتشمل أوجه الدعم توفير الإرشاد والتوجيه، ومساحات العمل المشتركة، والمساعدة في تطوير نموذج الأعمال، إضافة إلى منح مالية قد تصل إلى 150 ألف ريال بحسب مسار البرنامج وشروط الاستحقاق. ويساعد ذلك أصحاب المشاريع على تقليل التكاليف المرتبطة بالمراحل المبكرة من تطوير المنتج والاستعداد لدخول السوق.$q$,$q$https://ntdp.mcit.gov.sa/mvplab$q$,$q$https://ntdp.mcit.gov.sa/mvplab$q$,array[$q$تطوير المنتجات$q$,$q$منح$q$,$q$إرشاد$q$]::text[],array[$q$fund$q$,$q$mentor$q$,$q$prod$q$,$q$space$q$]::text[],null,1),
  (2,$q$o1$q$,$q$مبادرة الجيل القادم – NEXT ERA$q$,$q$تركز مبادرة NEXT ERA على دعم تطوير المنتجات والحلول التقنية المبتكرة، خصوصًا في مجالات التقنيات الناشئة والعميقة. وتهدف إلى تحفيز تحويل نتائج البحث والتطوير والابتكارات التقنية إلى منتجات يمكن الاستفادة منها تجاريًا، من خلال حوافز موجهة للأفراد والشركات التقنية المؤهلة. وتكتسب المبادرة أهمية خاصة للباحثين والمبتكرين الذين يمتلكون تقنيات أو نتائج بحثية ذات إمكانات تطبيقية، لكنهم يحتاجون إلى موارد إضافية لاستكمال التطوير والتحقق من جاهزية المنتج. ويساعد هذا النوع من الدعم على تقليص الفجوة بين المخرجات البحثية والتطبيقات التجارية، وتشجيع إنشاء منتجات تقنية ذات قيمة مضافة في السوق السعودي.$q$,$q$https://ntdp.mcit.gov.sa/nextera$q$,$q$https://ntdp.mcit.gov.sa/nextera$q$,array[$q$تطوير التقنيات العميقة$q$,$q$حوافز مالية$q$]::text[],array[$q$fund$q$,$q$prod$q$]::text[],null,2),
  (3,$q$o3$q$,$q$مبادرة محفزات تبني التقنية – AdopTech$q$,$q$تستهدف المبادرة تحفيز منشآت القطاع الخاص على تبني التقنيات الناشئة والممكنات الرقمية، بما يشمل الحلول السحابية والمنتجات التقنية الحديثة. وتركز على قطاعات الصناعة والخدمات اللوجستية والطاقة والتعدين، من خلال مسارين هما تبني الممكنات الرقمية، وتطوير إثبات المفهوم لحالات استخدام التقنيات الناشئة. ويمكن للشركات التقنية ومطوري الحلول المبتكرة الاستفادة من المبادرة عبر إتاحة الفرصة لتطبيق تقنياتهم في بيئات تشغيلية حقيقية، والتحقق من جدواها الفنية والاقتصادية. كما تساعد المنشآت المستفيدة على رفع كفاءتها وتحسين عملياتها التشغيلية، وتوفر فرصًا للتعاون بين مطوري التقنية والجهات التي تحتاج إلى حلول رقمية متخصصة.$q$,$q$https://mcit.gov.sa/ar/eti$q$,$q$https://mcit.gov.sa/ar/eti$q$,array[$q$تجربة التقنية$q$,$q$إثبات المفهوم$q$,$q$التحول الرقمي$q$]::text[],array[$q$prod$q$,$q$tech$q$]::text[],null,3),
  (4,$q$o4$q$,$q$برنامج AI Catalyst – محفز الذكاء الاصطناعي$q$,$q$يستهدف البرنامج رواد الأعمال والشركات الناشئة التي تطور منتجات وحلولًا تقنية تعتمد على الذكاء الاصطناعي. ويوفر للمشاركين خدمات الدعم الفني والتقني، وورش العمل المتخصصة، والإرشاد الريادي، والتواصل مع الخبراء والمستثمرين والشركاء المحتملين. ويمتد البرنامج على مدى أربعة أشهر، من خلال مراكز كود في مناطق المملكة. ويساعد أصحاب المشاريع على تحسين النماذج الأولية، وتطوير نماذج أعمال قابلة للنمو، والتحقق من ملاءمة الحلول لاحتياجات العملاء، ورفع جاهزية المنتجات للدخول إلى السوق. ويعد فرصة مناسبة للمشاريع التقنية في مراحلها المبكرة، التي تجاوزت مرحلة الفكرة وتحتاج إلى بيئة داعمة لتطوير المنتج والتوسع التجاري.$q$,$q$https://code.datalexing.sa/ar/public/form/XH-dlY63nr58sFBOVAcXjenrjMKyXEkdbB4AsE71EmY?view=form$q$,$q$https://code.datalexing.sa/ar/public/form/XH-dlY63nr58sFBOVAcXjenrjMKyXEkdbB4AsE71EmY?view=form$q$,array[$q$احتضان$q$,$q$تطوير منتجات الذكاء الاصطناعي$q$]::text[],array[$q$incub$q$,$q$prod$q$,$q$tech$q$]::text[],null,4),
  (5,$q$o1$q$,$q$مبادرة BOOST$q$,$q$تهدف مبادرة BOOST إلى دعم مؤسسي الشركات التقنية السعودية الناشئة، وتمكينهم من تخصيص وقتهم وجهودهم لتطوير مشاريعهم الريادية خلال المراحل المبكرة. وتقدم المبادرة دعمًا ماليًا وأدوات وموارد مساندة تساعد المؤسسين على الاستمرار في تطوير الأعمال، وتحسين قدراتهم الإدارية والريادية. وتستهدف الشركات التقنية التي تحتاج إلى مساندة خلال مرحلة بناء المشروع وتطوير المنتج والاستعداد للنمو. ويمكن أن تسهم هذه المبادرة في تخفيف بعض الأعباء المالية التي تواجه رواد الأعمال في بداية تأسيس شركاتهم، بما يمنحهم فرصة أكبر للتركيز على تطوير الحلول التقنية، وبناء فريق العمل، والتحقق من فرص السوق والتوجهات التجارية.$q$,$q$https://ntdp.mcit.gov.sa/boost$q$,$q$https://ntdp.mcit.gov.sa/boost$q$,array[$q$دعم مالي للمؤسسين$q$]::text[],array[$q$fund$q$]::text[],null,5),
  (6,$q$o1$q$,$q$مبادرة TRANSFORM+$q$,$q$تسعى مبادرة TRANSFORM+ إلى تسريع تبني تقنيات الحوسبة السحابية لدى الشركات الناشئة، ودعم انتقالها إلى بيئات تقنية أكثر كفاءة وقابلية للتوسع. وتقدم المبادرة منحًا مالية قد تصل إلى مليون ريال للشركة المستفيدة وفق شروط الاستحقاق، بهدف معالجة الفجوة التقنية التي قد تعيق نمو المشاريع وتطور منتجاتها الرقمية. وتستفيد منها الشركات التي تحتاج إلى تطوير بنيتها التقنية أو تحديث أنظمتها بما ينسجم مع متطلبات التشغيل والنمو. ويمكن أن يكون الدعم ذا أهمية للشركات التي تقدم خدمات رقمية أو تطبيقات تعتمد على معالجة البيانات، حيث تساعد البنية السحابية المناسبة على تحسين الأداء وإدارة الموارد والتوسع في تقديم الخدمات.$q$,$q$https://ntdp.mcit.gov.sa/transform$q$,$q$https://ntdp.mcit.gov.sa/transform$q$,array[$q$منح مالية$q$,$q$خدمات الحوسبة السحابية$q$]::text[],array[$q$fund$q$,$q$tech$q$]::text[],null,6),
  (7,$q$o1$q$,$q$مبادرة LendTech – تمويل الشركات التقنية$q$,$q$تقدم مبادرة LendTech حلولًا تمويلية متخصصة للشركات العاملة في قطاع تقنية المعلومات، بهدف تسهيل حصولها على التمويل اللازم للتأسيس والتوسع وتطوير عملياتها التجارية. وتراعي المبادرة طبيعة الشركات التقنية واحتياجاتها التمويلية، التي قد تختلف عن متطلبات الأنشطة التقليدية. وتتاح الخدمة بالتعاون مع بنك التنمية الاجتماعية، حيث تشير منصة الخدمات الحكومية إلى إمكانية الحصول على تمويل يصل إلى 8.5 ملايين ريال وفق شروط المنتج. ويمكن للشركات المستفيدة توظيف التمويل في دعم العمليات وتطوير قدراتها التشغيلية، بما يساعدها على تنفيذ خطط النمو وتحسين قدرتها التنافسية والاستفادة من الفرص المتاحة في سوق التقنية.$q$,$q$https://ntdp.mcit.gov.sa/lendtech$q$,$q$https://ntdp.mcit.gov.sa/lendtech$q$,array[$q$تمويل وقروض$q$]::text[],array[$q$fund$q$]::text[],null,7),
  (8,$q$o1$q$,$q$مبادرة CONNECT – دعم التمكين$q$,$q$تستهدف مبادرة CONNECT تمكين الشركات التقنية المتناهية الصغر والصغيرة والمتوسطة من المنافسة على المشاريع التقنية الكبرى، من خلال رفع جاهزيتها وقدرتها على إثبات إمكاناتها التنفيذية. وتشمل المبادرة تقديم منح مالية قد تصل إلى 740 ألف ريال للشركات المؤهلة، وفق المتطلبات المحددة. وتساعد المبادرة الشركات على تجاوز بعض التحديات المرتبطة بالمشاركة في الفرص التجارية الكبيرة، بما في ذلك الحاجة إلى إثبات القدرة الفنية والتشغيلية على تنفيذ المشاريع. وتعد مناسبة للشركات التي تمتلك حلولًا ومنتجات تقنية قابلة للتطبيق وترغب في التوسع نحو العملاء المؤسسيين والجهات ذات المشاريع الكبيرة.$q$,$q$https://ntdp.mcit.gov.sa/connect$q$,$q$https://ntdp.mcit.gov.sa/connect$q$,array[$q$منح مالية$q$,$q$الوصول إلى المشاريع التقنية الكبرى$q$]::text[],array[$q$fund$q$]::text[],null,8),
  (9,$q$o1$q$,$q$برنامج TECHCREW$q$,$q$يهدف برنامج TECHCREW إلى دعم الشركات التقنية المتناهية الصغر والصغيرة والمتوسطة في استقطاب الكفاءات الوطنية المتخصصة في مجالات تقنية المعلومات. ويقدم البرنامج دعمًا ماليًا مباشرًا يساعد المنشآت المستفيدة على بناء فرق العمل المتخصصة اللازمة لتطوير المنتجات والخدمات وتنفيذ خطط النمو. ويستهدف معالجة أحد التحديات الرئيسية التي تواجه الشركات التقنية الناشئة، والمتمثل في ارتفاع تكاليف توظيف المهارات التقنية المطلوبة. ويمكن الاستفادة منه في دعم بناء الفرق المسؤولة عن تطوير البرمجيات وإدارة المنتجات والخدمات الرقمية وغيرها من التخصصات المؤهلة. ويساعد ذلك الشركات على تعزيز قدراتها التشغيلية، وتسريع تنفيذ مشاريعها، ورفع جاهزيتها للتوسع في السوق.$q$,$q$https://ntdp.mcit.gov.sa/techcrew$q$,$q$https://ntdp.mcit.gov.sa/techcrew$q$,array[$q$حوافز مالية لتوظيف الكفاءات التقنية$q$]::text[],array[$q$fund$q$]::text[],null,9),
  (10,$q$o1$q$,$q$برنامج تمكين – TAMKEEN$q$,$q$يهدف برنامج تمكين إلى دعم الشركات التقنية المتناهية الصغر والصغيرة والمتوسطة في المحافظة على الكفاءات السعودية المتخصصة، وتعزيز الاستقرار الوظيفي واستدامة نمو الأعمال. ويقدم البرنامج حوافز مالية موزعة على ثلاث مراحل خلال 18 شهرًا، قد تصل قيمتها إلى 86 ألف ريال لكل موظف مستوفٍ للشروط. ويشمل تخصصات تقنية متعددة، منها تطوير البرمجيات وهندسة الشبكات وعلوم البيانات والأمن السيبراني. ويساعد البرنامج الشركات الناشئة على تخفيف الأعباء المرتبطة باستبقاء الموظفين المؤهلين، وتحسين قدرتها على بناء فرق مستقرة، بما يدعم استمرارية تطوير المنتجات والخدمات التقنية وتحقيق أهداف النمو.$q$,$q$https://ntdp.mcit.gov.sa/tamkeen$q$,$q$https://ntdp.mcit.gov.sa/tamkeen$q$,array[$q$حوافز مالية لاستبقاء الموظفين$q$]::text[],array[$q$fund$q$]::text[],null,10),
  (11,$q$o4$q$,$q$برنامج Tech Founders$q$,$q$يهدف البرنامج إلى تمكين مؤسسي الشركات التقنية السعودية الواعدة من تطوير أعمالهم والتوسع نحو الأسواق الدولية. ويوفر رحلة تطوير تجمع بين التدريب الريادي، وبناء القدرات الاستثمارية، والإرشاد من الخبراء، والتواصل مع المستثمرين والشركاء الاستراتيجيين محليًا ودوليًا. كما يتيح للمشاركين الاستفادة من تجارب منظومات ريادة الأعمال العالمية والتعرف على متطلبات دخول الأسواق الجديدة. ويركز البرنامج على الشركات التي تمتلك منتجات تقنية وفرصًا للنمو، وتسعى إلى تحسين نماذج أعمالها وتعزيز جاهزيتها للاستثمار. ويساعد ذلك مؤسسي الشركات على بناء علاقات تجارية واستثمارية جديدة، والاستعداد للتوسع بصورة أكثر تنظيمًا واستدامة.$q$,$q$https://code.datalexing.sa/ar/public/form/z5AQOBokEW8umNfdDr4mbla1KMWl8suPw5MO1FeAIUE?view=form$q$,$q$https://code.datalexing.sa/ar/public/form/z5AQOBokEW8umNfdDr4mbla1KMWl8suPw5MO1FeAIUE?view=form$q$,array[$q$تسريع الأعمال$q$,$q$التوسع العالمي$q$,$q$الجاهزية الاستثمارية$q$]::text[],array[$q$invest$q$,$q$incub$q$,$q$market$q$]::text[],null,11),
  (12,$q$o4$q$,$q$برنامج الاحتضان – CODE Incubation$q$,$q$يوفر برنامج الاحتضان بيئة عمل مخصصة لرواد الأعمال والشركات الناشئة في القطاع التقني، من خلال مساحات عمل مجهزة بالمرافق والأدوات اللازمة لتطوير المشاريع وإدارة أنشطتها. ويساعد البرنامج أصحاب المشاريع في مختلف مراحل النمو على الاستفادة من بيئة تجمع رواد الأعمال والخبراء والجهات الداعمة، بما يعزز فرص التعاون وتبادل الخبرات. ويستفيد المشاركون من مرافق العمل والخدمات المرتبطة بتطوير الأعمال، إلى جانب التواصل مع المجتمع الريادي داخل مراكز كود. ويعد البرنامج مناسبًا للمشاريع التقنية التي تحتاج إلى مقر داعم وبيئة مهنية تساعد الفريق على تطوير المنتج وتوسيع شبكة العلاقات والاستعداد للانطلاق التجاري.$q$,$q$https://mcit.gov.sa/ar/code$q$,$q$https://mcit.gov.sa/ar/code$q$,array[$q$احتضان$q$,$q$مساحات عمل$q$,$q$خدمات أعمال$q$]::text[],array[$q$incub$q$,$q$space$q$]::text[],null,12),
  (13,$q$o4$q$,$q$برنامج CODE Nine66 – كود ناين 66$q$,$q$برنامج متخصص في دعم رواد الأعمال والمطورين والمصممين والفنانين العاملين في مجال الألعاب الإلكترونية. يجمع البرنامج بين فعاليات تطوير الألعاب الجماعية (Game Jam) واحتضان المشاريع الواعدة، بهدف تحويل الأفكار الإبداعية إلى ألعاب إلكترونية قابلة للإطلاق التجاري. ويتيح للمشاركين تطوير مهارات تصميم الألعاب وبرمجتها وتحسين تجربة المستخدم، والعمل على تطوير نماذج ألعاب يمكن عرضها واختبارها. كما يهدف إلى مساعدة الفرق على تأسيس استوديوهات ألعاب قادرة على النمو والمنافسة في السوق. ويستهدف المبتكرين الذين يمتلكون أفكارًا أو مشاريع في صناعة الألعاب، ويرغبون في الاستفادة من بيئة ريادية متخصصة لتطوير منتجاتهم.$q$,$q$https://code.datalexing.sa/ar/public/form/R4QiRh491RLqRyJ31Xe38MeR3aLlH-MMpR5K-kFGaVw?view=form$q$,$q$https://code.datalexing.sa/ar/public/form/R4QiRh491RLqRyJ31Xe38MeR3aLlH-MMpR5K-kFGaVw?view=form$q$,array[$q$تطوير الألعاب الإلكترونية$q$,$q$احتضان المشاريع$q$]::text[],array[$q$incub$q$,$q$prod$q$]::text[],null,13),
  (14,$q$o4$q$,$q$برنامج الابتكار المؤسسي – Corporate Innovation Program$q$,$q$يستهدف البرنامج تعزيز الابتكار في الشركات والمؤسسات من خلال تطوير قدرات القيادات وفرق العمل على تبني منهجيات الابتكار المفتوح، والتعاون مع الشركات الناشئة ومطوري التقنيات الجديدة. ويساعد المشاركين على التعرف على الفرص التقنية داخل مؤسساتهم، وتطوير آليات لاستكشاف الحلول المبتكرة وتقييمها، وبناء شراكات مع الجهات التي تمتلك منتجات وتقنيات واعدة. ويمكن أن يستفيد منه المبتكرون بصورة غير مباشرة من خلال توفير فرص لربط حلولهم التقنية باحتياجات الشركات الكبرى. وتبرز أهميته في تسهيل الانتقال من تطوير المنتج إلى اختباره لدى عملاء مؤسسيين محتملين، بما يعزز فرص التبني التجاري والتوسع.$q$,$q$https://mcit.gov.sa/ar/news/%D9%88%D8%B2%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D8%A7%D8%AA%D8%B5%D8%A7%D9%84%D8%A7%D8%AA-%D8%AA%D8%B7%D9%84%D9%82-%D8%A7%D9%84%D9%86%D8%B3%D8%AE%D8%A9-%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A%D8%A9-%D9%85%D9%86-%D8%A8%D8%B1%D9%86%D8%A7%D9%85%D8%AC-%D8%A7%D9%84%D8%A7%D8%A8%D8%AA%D9%83%D8%A7%D8%B1-%D8%A7%D9%84%D9%85%D8%A4%D8%B3%D8%B3%D9%8A-%D9%84%D8%AA%D9%85%D9%83%D9%8A%D9%86-%D8%A7%D9%84%D8%B4%D8%B1%D9%83%D8%A7%D8%AA-%D9%88%D9%81%D8%AA%D8%AD-%D9%81%D8%B1%D8%B5-%D8%AC%D8%AF%D9%8A%D8%AF%D8%A9$q$,$q$https://mcit.gov.sa/ar/news/%D9%88%D8%B2%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D8%A7%D8%AA%D8%B5%D8%A7%D9%84%D8%A7%D8%AA-%D8%AA%D8%B7%D9%84%D9%82-%D8%A7%D9%84%D9%86%D8%B3%D8%AE%D8%A9-%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A%D8%A9-%D9%85%D9%86-%D8%A8%D8%B1%D9%86%D8%A7%D9%85%D8%AC-%D8%A7%D9%84%D8%A7%D8%A8%D8%AA%D9%83%D8%A7%D8%B1-%D8%A7%D9%84%D9%85%D8%A4%D8%B3%D8%B3%D9%8A-%D9%84%D8%AA%D9%85%D9%83%D9%8A%D9%86-%D8%A7%D9%84%D8%B4%D8%B1%D9%83%D8%A7%D8%AA-%D9%88%D9%81%D8%AA%D8%AD-%D9%81%D8%B1%D8%B5-%D8%AC%D8%AF%D9%8A%D8%AF%D8%A9$q$,array[$q$الابتكار المفتوح$q$,$q$الشراكات بين الشركات$q$]::text[],array[$q$market$q$]::text[],null,14),
  (15,$q$o4$q$,$q$برنامج الشركات المليارية السعودية – Saudi Unicorns$q$,$q$يستهدف برنامج الشركات المليارية السعودية الشركات التقنية ذات النمو المتسارع والإمكانات العالية للتوسع، من خلال توفير مجموعة من الخدمات والممكنات المتخصصة التي تساعدها على الوصول إلى مراحل نمو متقدمة. وتشمل أوجه الدعم تطوير قدرات مؤسسي الشركات وقياداتها، وربطها بصناديق الاستثمار وشبكات الخبراء، وتسهيل فرص التوسع في الأسواق الإقليمية والعالمية. كما يعمل البرنامج على معالجة التحديات التي تواجه الشركات خلال مراحل التوسع السريع، وتعزيز جاهزيتها لجولات التمويل والنمو المؤسسي. ويعد مناسبًا للشركات التقنية التي أثبتت نجاح نموذج أعمالها وحققت مؤشرات نمو قوية، وتطمح إلى الوصول لقيمة سوقية تتجاوز مليار دولار.$q$,$q$https://ntdp.mcit.gov.sa/saudi-unicorn$q$,$q$https://ntdp.mcit.gov.sa/saudi-unicorn$q$,array[$q$تسريع النمو$q$,$q$استثمار$q$,$q$توسع دولي$q$]::text[],array[$q$invest$q$,$q$incub$q$,$q$market$q$]::text[],null,15),
  (16,$q$o4$q$,$q$خدمة الدعم التقني – CODE Technical Support$q$,$q$تقدم الخدمة دعمًا فنيًا وتقنيًا للمبتكرين ورواد الأعمال خلال مراحل تطوير مشاريعهم، بدءًا من الفكرة وحتى بناء النموذج الأولي والاستعداد لدخول السوق. وتشمل المساندة الاستفادة من خبرات المختصين في الجوانب التقنية والتطبيقية، والحصول على الاستشارات اللازمة لتطوير الحلول وتحسين جودة المنتجات. كما تتضمن الاستفادة من معامل الابتكار والنمذجة الأولية والأدوات التقنية المتاحة ضمن منظومة كود، بحسب طبيعة المشروع والخدمات المقدمة. وتساعد هذه الخدمة أصحاب المشاريع على معالجة التحديات الفنية التي قد تواجههم أثناء التطوير، والتحقق من قابلية تنفيذ الحلول، وتحسين المنتجات قبل الانتقال إلى مراحل الإنتاج أو الإطلاق التجاري.$q$,$q$https://mcit.gov.sa/code$q$,$q$https://mcit.gov.sa/code$q$,array[$q$استشارات تقنية$q$,$q$تطوير نماذج أولية$q$]::text[],array[$q$mentor$q$,$q$prod$q$]::text[],null,16),
  (17,$q$o4$q$,$q$خدمة الإرشاد والتوجيه – CODE Mentorship & Guidance$q$,$q$توفر الخدمة جلسات إرشادية متخصصة لرواد الأعمال وأصحاب المشاريع التقنية، بهدف مساعدتهم على اتخاذ القرارات المتعلقة بتطوير المنتجات ونماذج الأعمال والاستعداد لدخول السوق. وتتيح للمستفيدين الاستفادة من خبرات المختصين في المجالات التقنية والريادية، ومناقشة التحديات التي تواجه مشاريعهم، وتحديد فرص التحسين والتطوير. ويمكن أن تشمل موضوعات الإرشاد اختيار نموذج الأعمال المناسب، وفهم احتياجات العملاء، وتحديد متطلبات التطوير التقني، والاستعداد للتوسع. وتكتسب الخدمة أهمية للمشاريع في مراحلها المبكرة التي تحتاج إلى توجيه متخصص يساعدها على تجنب بعض الأخطاء الشائعة وتوظيف مواردها بصورة أكثر فاعلية.$q$,$q$https://mcit.gov.sa/code$q$,$q$https://mcit.gov.sa/code$q$,array[$q$إرشاد ريادي وتقني$q$]::text[],array[$q$mentor$q$]::text[],null,17),
  (18,$q$o1$q$,$q$برنامج LEAD IT – تطوير القيادات التقنية$q$,$q$يهدف برنامج LEAD IT إلى تطوير الكفاءات القيادية في الشركات التقنية، من خلال تنمية المهارات الإدارية والرقمية اللازمة لتولي مسؤوليات متقدمة في القطاع. ويستهدف بصورة خاصة الكفاءات المتوسطة الخبرة داخل الشركات الناشئة والمنشآت التقنية الصغيرة والمتوسطة. ويركز على إعداد المشاركين لإدارة الفرق والمشاريع والعمليات التقنية بصورة أكثر فاعلية، مع تعزيز قدراتهم على اتخاذ القرارات وتطوير الأعمال. ويستفيد منه مؤسسو الشركات والكوادر المرشحة لتولي المناصب القيادية، حيث يسهم في بناء فرق إدارية قادرة على مواكبة توسع الشركات والتعامل مع التحديات التنظيمية والتشغيلية المرتبطة بالنمو.$q$,$q$https://ntdp.mcit.gov.sa/leadit$q$,$q$https://ntdp.mcit.gov.sa/leadit$q$,array[$q$تدريب قيادي وإداري$q$]::text[],array[$q$train$q$]::text[],null,18),
  (19,$q$o3$q$,$q$معسكرات مهارات المستقبل – Future Skills Bootcamps$q$,$q$تقدم معسكرات مهارات المستقبل برامج تدريبية مكثفة لتطوير المعرفة التقنية والمهارات التطبيقية في مجالات متعددة، تشمل الذكاء الاصطناعي والأمن السيبراني وتحليل البيانات والحوسبة السحابية وتطوير التطبيقات وغيرها. ويجري تنفيذ المعسكرات بالتعاون مع شركاء التدريب، مع التركيز على التطبيقات العملية وتنفيذ المشاريع التي تحاكي احتياجات سوق العمل. وتستهدف المعسكرات في مساراتها المعلنة المواطنين السعوديين المؤهلين والباحثين عن عمل وفق شروط القبول. ويمكن للمبتكرين والمهتمين بتأسيس المشاريع التقنية الاستفادة من هذه البرامج في اكتساب المهارات اللازمة لتطوير الحلول الرقمية وبناء المنتجات التقنية، وإن كانت موجهة أساسًا لتطوير الكفاءات المهنية.$q$,$q$https://futureskills.mcit.gov.sa/$q$,$q$https://futureskills.mcit.gov.sa/$q$,array[$q$تدريب تقني مكثف$q$]::text[],array[$q$train$q$]::text[],null,19),
  (20,$q$o3$q$,$q$الدورات التدريبية التخصصية – Specialized Training Courses$q$,$q$تقدم هذه الخدمة دورات تدريبية متخصصة في المجالات التقنية والرقمية الواعدة، من خلال مبادرة مهارات المستقبل وبالتعاون مع شركاء التدريب. وتشمل مجالات التدريب الذكاء الاصطناعي، وتحليل البيانات، وتطوير البرمجيات، والأمن السيبراني، والحوسبة السحابية، وإدارة المشاريع التقنية وغيرها. وتوفر الدورات للمشاركين فرصًا لتطوير معارفهم ومهاراتهم المهنية، مع شهادات اجتياز للبرامج المستوفية لمتطلباتها. ويمكن لرواد الأعمال وأعضاء الفرق التقنية الاستفادة منها في رفع قدراتهم على تطوير المنتجات وإدارة الحلول الرقمية. وتخضع المشاركة لشروط تختلف بحسب البرنامج، بما يشمل المؤهل العلمي والتخصص والفئة المستهدفة.$q$,$q$https://futureskills.mcit.gov.sa/ar/node/1553$q$,$q$https://futureskills.mcit.gov.sa/ar/node/1553$q$,array[$q$تدريب$q$,$q$تطوير مهارات$q$]::text[],array[$q$train$q$]::text[],null,20),
  (21,$q$o5$q$,$q$برنامج ألف ميل لريادة الأعمال (1000 Miles)$q$,$q$يهدف البرنامج إلى تمكين رواد الأعمال من تحويل أفكارهم ومشاريعهم المبتكرة إلى مشاريع استثمارية مستدامة في قطاعات الصناعة والتعدين والخدمات اللوجستية وتطوير المنتجات الدفاعية. يقدم البرنامج رحلة تأهيلية تشمل التدريب المتخصص في الجوانب الفنية والمالية والتسويقية، والزيارات الميدانية للمصانع والمرافق الصناعية، والاستشارات المتعلقة بدراسة الجدوى وتطوير نماذج الأعمال. كما يتيح للمشاركين التواصل مع الجهات الحكومية والمستثمرين وصناديق التمويل، والاستفادة من فرص المشاركة في المعارض والمؤتمرات. وتتاح للمشاريع المؤهلة فرصة المنافسة على منح مالية، بما يساعد رواد الأعمال على تطوير أفكارهم ورفع جاهزيتها للتحول إلى مشاريع تجارية.$q$,$q$https://1kmile.daleel.gov.sa$q$,$q$1kmile.daleel.gov.sa$q$,array[$q$احتضان ريادي$q$,$q$تدريب$q$,$q$استشارات فنية$q$,$q$ربط بالمستثمرين$q$,$q$منح مالية تنافسية$q$]::text[],array[$q$fund$q$,$q$invest$q$,$q$mentor$q$,$q$incub$q$,$q$train$q$]::text[],null,21),
  (22,$q$o5$q$,$q$برنامج المنتجات الصناعية والتعدينية المبتكرة$q$,$q$يستهدف البرنامج المبتكرين والباحثين والطلاب ورواد الأعمال والمنشآت الصغيرة والمتوسطة الذين يمتلكون أفكارًا أو منتجات مبتكرة في المجالات الصناعية والتعدينية. ويوفر رحلة تطوير تتكون من تسع مراحل، تبدأ من استقبال الأفكار وتقييمها، مرورًا بتطوير النماذج الأولية والتدريب والإرشاد، وصولًا إلى فرص التمويل والإنتاج والتصدير. ويشمل قطاعات صناعية متعددة مثل المعدات الطبية، والطيران، والصناعات الكيميائية، والسيارات، ومواد البناء، والتقنيات الحيوية. ويركز البرنامج على تحويل المخرجات البحثية والأفكار الابتكارية إلى منتجات قابلة للتصنيع والتسويق، وتعزيز التعاون مع الجامعات وحاضنات الأعمال والشركات الصناعية، بما يسهم في توطين المعرفة والتقنيات الصناعية.$q$,$q$https://www.mim.gov.sa/ar/initiatives-programs/innovation-program$q$,$q$https://www.mim.gov.sa/ar/initiatives-programs/innovation-program$q$,array[$q$تطوير الابتكارات$q$,$q$نماذج أولية$q$,$q$تدريب$q$,$q$إرشاد$q$,$q$تمكين التصنيع$q$]::text[],array[$q$mentor$q$,$q$train$q$,$q$prod$q$]::text[],null,22),
  (23,$q$o5$q$,$q$حاضنات ومسرعات الأعمال الصناعية «نمو»$q$,$q$تقدم خدمة «نمو» مسارات احتضان وتسريع مخصصة للشركات الصناعية الناشئة ورواد الأعمال الراغبين في تأسيس مشاريع إنتاجية أو تطوير مشاريعهم القائمة. وتتيح للمستثمرين التقديم على حاضنة أعمال صناعية أو مسرعة أعمال بحسب مرحلة المشروع ودرجة نضجه. وتهدف إلى تقديم برامج منظمة لدعم النمو والتطوير، ومساعدة رواد الأعمال على الانتقال من المراحل الأولية إلى مراحل أكثر تقدمًا في تأسيس وتشغيل المنشآت الصناعية. ويمكن أن يستفيد منها أصحاب الابتكارات الذين يحتاجون إلى توجيه متخصص في الجوانب الصناعية والتجارية، أو إلى تطوير قدرات مشاريعهم بما يؤهلها للدخول إلى السوق والتوسع في الإنتاج.$q$,$q$https://www.mim.gov.sa/ar/initiatives-programs/industrial-sector-initiatives/industrial-incubators-and-accelerators-initiative-numu$q$,$q$https://www.mim.gov.sa/ar/initiatives-programs/industrial-sector-initiatives/industrial-incubators-and-accelerators-initiative-numu$q$,array[$q$احتضان$q$,$q$تسريع أعمال$q$,$q$تطوير المشاريع الصناعية.$q$]::text[],array[$q$incub$q$]::text[],null,23),
  (24,$q$o5$q$,$q$برنامج مصانع المستقبل – Future Factories Program$q$,$q$يهدف برنامج مصانع المستقبل إلى رفع مستوى تبني التقنيات الصناعية المتقدمة في المصانع السعودية، وتحويلها من أساليب الإنتاج التقليدية إلى التشغيل الذكي والأتمتة. ويستهدف البرنامج تمكين 4,000 مصنع من الاستفادة من حلول الثورة الصناعية الرابعة، بما يشمل الأنظمة الرقمية، والروبوتات الصناعية، وتحليل البيانات، والتحكم الذكي في العمليات الإنتاجية. ويتيح للمصانع المشاركة تقييم مستوى نضجها الرقمي وتحديد فرص التحسين وتطوير خطط التحول التقني. وتبرز أهمية البرنامج للمبتكرين والشركات التقنية التي تطور حلولًا صناعية، إذ يوفر فرصًا لتطبيق منتجاتهم لدى المصانع المستفيدة، ويساعد أصحاب المنشآت الصناعية على تحسين الإنتاجية والتنافسية.$q$,$q$https://industry.sa/ar/programs/future-factories$q$,$q$https://industry.sa/ar/programs/future-factories$q$,array[$q$تحول صناعي$q$,$q$تقييم تقني$q$,$q$أتمتة$q$,$q$تطوير الإنتاج$q$]::text[],array[$q$prod$q$,$q$tech$q$,$q$ip$q$]::text[],null,24),
  (25,$q$o5$q$,$q$منح الثورة الصناعية الرابعة$q$,$q$تستهدف هذه الخدمة دعم المصانع في تطبيق حلول الرقمنة والأتمتة الأساسية التي تمثل خطوة نحو تبني التقنيات الصناعية المتقدمة. وتشمل الحلول المؤهلة رقمنة الإجراءات والتخطيط، وأنظمة الاتصالات والتحكم بخطوط الإنتاج، وآلات مناولة المواد والتغليف، وغيرها من الممكنات التقنية. وتقدم المنحة دعمًا يصل إلى 80% من قيمة المشروع، بحد أقصى 300 ألف ريال سعودي، وفق اشتراطات الأهلية. وتتيح الخدمة للمصانع تحسين أنظمتها التشغيلية، كما يمكن أن توفر فرصًا تجارية لمطوري الحلول التقنية والمبتكرين الصناعيين الذين يقدمون أنظمة الأتمتة والتصنيع الذكي، من خلال تنفيذ مشاريع التحول الرقمي لدى المصانع المستفيدة.$q$,$q$https://www.mim.gov.sa/ar/services/fourth-industrial-revolution-program-grant$q$,$q$https://www.mim.gov.sa/ar/services/fourth-industrial-revolution-program-grant$q$,array[$q$منح مالية$q$,$q$أتمتة$q$,$q$رقمنة.$q$]::text[],array[$q$fund$q$,$q$tech$q$]::text[],null,25),
  (26,$q$o5$q$,$q$برنامج الحوافز المعيارية للقطاع الصناعي$q$,$q$يهدف البرنامج إلى جذب الاستثمارات الصناعية النوعية وتحفيز توطين الصناعات والمنتجات الجديدة في المملكة، لا سيما ضمن القطاعات ذات الأولوية في الاستراتيجية الوطنية للصناعة. ويقدم حوافز للمشاريع الصناعية المؤهلة وفق معايير ومتطلبات محددة، بما يساعد المستثمرين على تقليل بعض التكاليف المرتبطة بتأسيس المشاريع وتطويرها. ويستهدف البرنامج الاستثمارات القادرة على تعزيز سلاسل الإمداد المحلية ونقل المعرفة والتقنيات الصناعية وزيادة القيمة المضافة للاقتصاد الوطني. ويمكن أن يستفيد منه رواد الأعمال أصحاب المشاريع الصناعية المتقدمة والشركات التي تخطط لتأسيس خطوط إنتاج جديدة أو توطين تصنيع منتجات وتقنيات ذات أهمية استراتيجية.$q$,$q$https://www.mim.gov.sa/ar/services/standard-incentive$q$,$q$https://www.mim.gov.sa/ar/services/standard-incentive$q$,array[$q$حوافز استثمارية$q$,$q$توطين صناعي$q$,$q$تطوير منتجات$q$]::text[],array[$q$fund$q$,$q$invest$q$,$q$prod$q$,$q$market$q$]::text[],null,26),
  (27,$q$o5$q$,$q$مبادرة المصانع الواعدة «التمويل الميسر»$q$,$q$تهدف المبادرة إلى تمكين رواد الأعمال والمنشآت الصناعية الصغيرة والمتوسطة من تأسيس مشاريع صناعية جديدة، عبر توفير حلول تمويلية تراعي التحديات التي تواجه المستثمرين في المراحل المبكرة. وتركز على تخفيف بعض متطلبات الضمانات الشخصية والملاءة المالية التي قد تعيق حصول أصحاب المشاريع على التمويل الصناعي. وتساعد المبادرة المستثمرين المؤهلين على الانتقال من مرحلة دراسة المشروع إلى تأسيس النشاط الصناعي وبدء الإنتاج. وتكتسب أهمية للمبتكرين الذين يمتلكون منتجات جاهزة للتصنيع التجاري، لكنهم يحتاجون إلى تمويل لتجهيز خطوط الإنتاج وشراء المعدات وتطوير منشآتهم، مع خضوع التمويل لدراسة المشروع وشروط الصندوق.$q$,$q$https://www.sidf.gov.sa/ar/Initiatives/Industrial-Sector-Support-Initiative$q$,$q$https://www.sidf.gov.sa/ar/Initiatives/Industrial-Sector-Support-Initiative$q$,array[$q$تمويل صناعي ميسر$q$]::text[],array[$q$fund$q$]::text[],null,27),
  (28,$q$o5$q$,$q$مبادرة مصانع المستقبل – مسار حوافز مسرعة تنافسية$q$,$q$مبادرة تمويلية وتحفيزية تستهدف المنشآت الصناعية الراغبة في تطوير عمليات الإنتاج وتبني التقنيات الصناعية الحديثة. وتركز على تمويل المشاريع المرتبطة بالأتمتة والتحول الرقمي وتحسين كفاءة استهلاك الطاقة، بما يسهم في رفع إنتاجية المصانع وتقليل التكاليف التشغيلية. ويتيح المسار للمستثمرين الصناعيين الاستفادة من حلول تمويلية وحوافز مرتبطة بتنفيذ مشاريع التطوير التقني. ويمكن أن تستفيد الشركات التي تمتلك حلولًا مبتكرة في الأتمتة والتحكم الصناعي وإدارة الطاقة من الفرص التي تنشأ عن هذه المشاريع. وتختلف عن منح الثورة الصناعية الرابعة، إذ تعد مسارًا تمويليًا وتحفيزيًا ينفذه الصندوق الصناعي وفق شروطه ومتطلباته.$q$,$q$https://www.mim.gov.sa/ar/initiatives-programs/industrial-sector-initiatives/industrial-sector-support-initiative/future-factories-initiative-tanafusiya-accelerator-track$q$,$q$https://www.mim.gov.sa/ar/initiatives-programs/industrial-sector-initiatives/industrial-sector-support-initiative/future-factories-initiative-tanafusiya-accelerator-track$q$,array[$q$تمويل$q$,$q$أتمتة$q$,$q$رقمنة$q$,$q$كفاءة الطاقة$q$]::text[],array[$q$fund$q$,$q$incub$q$,$q$tech$q$]::text[],null,28),
  (29,$q$o5$q$,$q$منتج المصانع الجاهزة – MODON Ready-Built Factories$q$,$q$تتيح خدمة المصانع الجاهزة لرواد الأعمال وأصحاب المنشآت الصغيرة والمتوسطة استئجار مصانع مجهزة بالبنية التحتية والخدمات الأساسية، دون الحاجة إلى إنشاء مبنى صناعي من البداية. وتتوفر المصانع بمساحات ومواصفات مختلفة وفق المواقع المتاحة، وتشمل صالات إنتاج ومرافق خدمية ومساحات إدارية. وتستهدف صناعات متنوعة، منها الصناعات الغذائية والدوائية والمستلزمات الطبية والإلكترونيات والصناعات الخفيفة. وتساعد الخدمة أصحاب المنتجات المبتكرة على الانتقال من النماذج الأولية والإنتاج التجريبي إلى التصنيع التجاري، مع تقليل الوقت والجهد اللازمين لتجهيز المنشأة. ويخضع الحصول على المصنع لاشتراطات النشاط الصناعي وتوافر المواقع.$q$,$q$https://modon.gov.sa/ar-SA/Main-Products/readyfactory$q$,$q$https://modon.gov.sa/ar-SA/Main-Products/readyfactory$q$,array[$q$بنية تحتية$q$,$q$استئجار مصنع$q$,$q$تمكين التصنيع التجاري$q$]::text[],array[$q$prod$q$,$q$tech$q$,$q$space$q$,$q$market$q$]::text[],null,29),
  (30,$q$o5$q$,$q$مبادرة اسأل خبيرًا – Ask an Expert$q$,$q$تتيح المبادرة للمستثمرين ورواد الأعمال الحصول على استشارات فنية متخصصة من خبراء صندوق التنمية الصناعية السعودي، من خلال منصة «نوافذ» التابعة للهيئة العامة للمنشآت الصغيرة والمتوسطة «منشآت». وتشمل المجالات التي تغطيها الاستشارات عمليات التصنيع، والإنشاءات، والسلامة الصناعية، وغيرها من الموضوعات المرتبطة بالمشاريع التي تقع ضمن القطاعات المستهدفة بالصندوق. وتساعد المبادرة أصحاب المشاريع على مناقشة التحديات الفنية التي قد تواجههم عند تأسيس المنشآت الصناعية أو تطوير عمليات الإنتاج. كما يمكن للمبتكرين الاستفادة من خبرات المختصين في تقييم بعض جوانب الجاهزية الصناعية ومتطلبات تنفيذ المشاريع، بما يدعم اتخاذ قرارات أكثر استنادًا إلى الخبرة العملية.$q$,$q$https://www.sidf.gov.sa/ar/AdvisoryServices/Ask-Expert$q$,$q$https://www.sidf.gov.sa/ar/AdvisoryServices/Ask-Expert$q$,array[$q$استشارات فنية وصناعية$q$]::text[],array[$q$mentor$q$]::text[],null,30),
  (31,$q$o5$q$,$q$هاكاثون الصناعة – Industrial Hackathon$q$,$q$هاكاثون تنظمه منظومة الصندوق الصناعي لجمع المبتكرين والمطورين وأصحاب الأفكار الإبداعية للعمل على حلول للتحديات التي تواجه المصانع الوطنية. ويوفر الهاكاثون بيئة تنافسية لتطوير الأفكار والحلول التي تستجيب لاحتياجات القطاع الصناعي، ويستهدف المشاركين من مختلف التخصصات ذات العلاقة. ويتيح للمبتكرين فرصة فهم التحديات الحقيقية التي تواجه المنشآت الصناعية، وتطوير مقترحات تقنية وعملية لمعالجتها. كما يساعد على تشجيع التعاون بين أصحاب المهارات المختلفة وربط الابتكار باحتياجات الصناعة. ويمكن أن يمثل نقطة انطلاق لمشاريع ريادية جديدة تقوم على حلول صناعية ذات فرص تطبيق تجاري.$q$,$q$https://www.sidf.gov.sa/ar/Initiatives/Industrial-Hackathon$q$,$q$https://www.sidf.gov.sa/ar/Initiatives/Industrial-Hackathon$q$,array[$q$مسابقات ابتكار$q$,$q$تطوير حلول صناعية$q$,$q$ربط بالتحديات$q$]::text[],array[$q$prod$q$,$q$compete$q$]::text[],null,31),
  (32,$q$o5$q$,$q$خدمة الزيارة الافتراضية للمستثمرين$q$,$q$تتيح الخدمة للمستثمرين ورواد الأعمال التواصل المباشر مع مركز تواصل الشركاء في وزارة الصناعة والثروة المعدنية عبر الاتصال المرئي. وتهدف إلى تقديم الدعم والإجابة عن الاستفسارات المتعلقة بالخدمات والإجراءات والحوافز المتاحة للمستثمرين في قطاعي الصناعة والتعدين. ويمكن للمستفيدين استخدامها للتعرف على البرامج المناسبة لمشاريعهم، وفهم متطلبات الحصول على التراخيص الصناعية، والاستفسار عن آليات الاستفادة من الممكنات والحوافز المتاحة. وتعد الخدمة مفيدة بصورة خاصة للمبتكرين ورواد الأعمال الذين يخططون لتأسيس مشاريع صناعية ويحتاجون إلى توجيه أولي قبل البدء في الإجراءات الرسمية أو التقدم للبرامج المتخصصة.$q$,$q$https://vvisit.mim.gov.sa/ar$q$,$q$https://vvisit.mim.gov.sa/ar$q$,array[$q$استشارات أولية$q$,$q$توجيه المستثمر$q$,$q$التعريف بالحوافز$q$]::text[],array[$q$invest$q$,$q$mentor$q$,$q$prod$q$]::text[],null,32),
  (33,$q$o6$q$,$q$جولات في مركز الابتكار$q$,$q$جولات للفائزين في مسار الطاقة في مركز الابتكار لوزارة الطاقة، حيث يلتقي الابتكار والتقنيات الحديثة بالممكنات مثل غرف العصف الذهني ومنطقة التجارب والنمذجة ومرافق داعمة أخرى$q$,null,$q$التواصل مع إدارة حاضنة ابتكار بجامعة القصيم$q$,array[$q$جولات تعريفية$q$]::text[],array[$q$compete$q$]::text[],$q$التواصل مع إدارة حاضنة ابتكار بجامعة القصيم$q$,33),
  (34,$q$o6$q$,$q$مبادرة طاقتنا رقمية$q$,$q$حضور الورش والدورات التدريبية المقامة في وزارة الطاقة للفائزين في مسار الطاقة تحت مظلة مبادرة طاقتنا رقمية والتي تهدف للتعريف بالتقنيات الحديثة والابتكار في قطاع الطاقة$q$,null,$q$التواصل مع إدارة حاضنة ابتكار بجامعة القصيم$q$,array[$q$تدريب$q$,$q$ورش عمل$q$,$q$استشارات$q$]::text[],array[$q$mentor$q$,$q$train$q$]::text[],$q$التواصل مع إدارة حاضنة ابتكار بجامعة القصيم$q$,34),
  (35,$q$o6$q$,$q$حاضنة الابتكار للطاقة$q$,$q$تهدف الحاضنة إلى تحفيز وتمكين المشاريع ذات الأهداف الاجتماعية والبيئية وتعزيز ثقافة الابتكار الاجتماعي وريادة الأعمال الاجتماعية لتحقيق أثر أعمق في قطاع الطاقة. يندرج مشروع الحاضنة ضمن ركيزة المنشآت الاجتماعية في إستراتيجية التنمية المجتمعية لمنظومة الطاقة، كما أنها تساهم بشكل مباشر في الهدف الإستراتيجي المرتبط بهذه الركيزة وهو تكوين ثقافة المنشآت الاجتماعية وزيادة عدد المنشآت الاجتماعية المتخصصة في قطاع الطاقة.$q$,$q$https://www.moenergy.gov.sa/ar/ministry/about/initiatives/moenergy-incubator/about$q$,$q$https://www.moenergy.gov.sa/ar/ministry/about/initiatives/moenergy-incubator/about$q$,array[$q$احتضان$q$,$q$أرشاد$q$,$q$توجيه$q$]::text[],array[$q$mentor$q$,$q$incub$q$]::text[],null,35),
  (36,$q$o6$q$,$q$مسرّعة طاقتك – TAQATech Accelerator$q$,$q$مسرّعة أعمال أطلقتها وزارة الطاقة بالتعاون مع «الكراج» لدعم الشركات الناشئة التي تقدم حلولًا وتقنيات مبتكرة في قطاع الطاقة. يمتد البرنامج لأربعة أشهر، ويوفر ورش عمل متخصصة وجلسات إرشاد فردية مع خبراء القطاع، ومساحات عمل مشتركة وخاصة، إضافة إلى فرص التواصل مع المستثمرين والشركاء الاستراتيجيين. ويركز على تطوير المنتجات والتحقق من ملاءمتها للسوق، والجوانب القانونية والمالية والتسويقية، وصولًا إلى يوم عرض المشاريع أمام المستثمرين. ويتيح البرنامج للشركات المشاركة فرصًا لتطوير حلولها والتواصل مع الجهات العاملة في قطاع الطاقة، بما يدعم الانتقال من النماذج الأولية إلى التطبيقات التجارية. واختتمت الدفعة الأولى بمشاركة 21 شركة ناشئة.$q$,$q$https://www.moenergy.gov.sa/ar/ministry/initiatives/taqahtech-accelerator/about$q$,$q$https://www.moenergy.gov.sa/ar/ministry/initiatives/taqahtech-accelerator/about$q$,array[$q$تسريع أعمال$q$,$q$إرشاد تقني$q$,$q$تجارب تشغيلية$q$,$q$ربط بالمستثمرين$q$]::text[],array[$q$invest$q$,$q$mentor$q$,$q$incub$q$,$q$prod$q$,$q$market$q$]::text[],null,36),
  (37,$q$o6$q$,$q$حاضنة الطاقة – Energy Incubator$q$,$q$حاضنة أعمال أطلقتها وزارة الطاقة لدعم رواد الأعمال والمنشآت الناشئة التي تقدم أفكارًا ومشاريع ذات أثر اجتماعي وبيئي في قطاع الطاقة. توفر الحاضنة بيئة متكاملة لتطوير الأفكار وتحويلها إلى مشاريع قابلة للتنفيذ، من خلال مساحات عمل مجهزة، وورش عمل متخصصة، وجلسات إرشاد واستشارات تساعد المشاركين على تطوير نماذج أعمالهم وتحديد فرص السوق. كما تركز على دعم المشاريع التي تسهم في مواجهة التحديات المجتمعية المرتبطة بالطاقة وتعزيز الاستدامة وجودة الحياة. وتستهدف الحاضنة المشاريع في مراحلها المبكرة، وتساعد المؤسسين على بناء قدراتهم الريادية والاستعداد لإطلاق مشاريعهم ونموها بصورة مستدامة.$q$,$q$https://www.moenergy.gov.sa/ar/ministry/about/initiatives/moenergy-incubator/about$q$,$q$https://www.moenergy.gov.sa/ar/ministry/about/initiatives/moenergy-incubator/about$q$,array[$q$احتضان$q$,$q$تطوير مشاريع$q$,$q$استشارات$q$,$q$مساحات عمل$q$]::text[],array[$q$mentor$q$,$q$incub$q$,$q$prod$q$,$q$space$q$]::text[],null,37),
  (38,$q$o6$q$,$q$هاكاثون الطاقة – Energy Hackathon$q$,$q$مسابقة وطنية تنظمها وزارة الطاقة لتحفيز المبتكرين والباحثين ورواد الأعمال على تطوير حلول تقنية للتحديات الفعلية التي تواجه قطاع الطاقة. شملت نسخة عام 2026 ثلاثة مسارات رئيسية هي الابتكار التحولي، والكفاءة التشغيلية، والتحكم الذكي، وتناولت تحديات مثل تخزين الهيدروجين، وتصميم محطات الوقود، والصيانة التنبؤية، وإدارة الأحمال الكهربائية. وفرت المسابقة ورش عمل وجلسات إرشاد وتوجيه من خبراء القطاع، مع فرص لتطوير النماذج الأولية وعرض الحلول المبتكرة. وبلغ مجموع الجوائز أكثر من 500 ألف ريال، إلى جانب فرص تمكين المشاريع المتميزة وربطها بمنظومة الطاقة، بما يعزز إمكانية استكمال تطويرها وتطبيقها.$q$,$q$https://hackathon.moenergy.gov.sa/$q$,$q$https://hackathon.moenergy.gov.sa/$q$,array[$q$مسابقات ابتكار$q$,$q$تطوير نماذج أولية$q$,$q$إرشاد$q$,$q$جوائز مالية$q$]::text[],array[$q$fund$q$,$q$mentor$q$,$q$prod$q$,$q$compete$q$]::text[],null,38),
  (39,$q$o6$q$,$q$جائزة كفاءة الطاقة – مسار التطوير والابتكار$q$,$q$مسار ضمن جائزة كفاءة الطاقة يهدف إلى تشجيع تطوير الأفكار والحلول المبتكرة التي تسهم في رفع كفاءة استخدام الطاقة وتقليل الهدر في القطاعات المختلفة. ويتيح للمبتكرين والباحثين والمنشآت والجهات الحكومية وغير الربحية والأفراد المشاركة بحلول أو مبادرات ذات أثر في تحسين كفاءة الطاقة. ويركز المسار على إبراز الممارسات والتقنيات التي تقدم نتائج قابلة للقياس، وتشجيع تطوير حلول يمكن الاستفادة منها في التطبيقات العملية. وتتيح المشاركة فرصة لعرض الإنجازات الابتكارية والتعريف بها ضمن منظومة كفاءة الطاقة، بما يساعد أصحاب المشاريع على إبراز القيمة التقنية والاقتصادية والبيئية لابتكاراتهم أمام الجهات المهتمة.$q$,$q$https://eeaward.seec.gov.sa/en$q$,$q$https://eeaward.seec.gov.sa/en$q$,array[$q$مسابقات وجوائز$q$,$q$إبراز الابتكارات$q$]::text[],array[$q$compete$q$]::text[],null,39),
  (40,$q$o7$q$,$q$منصة بيانات السعودية – Data Saudi$q$,$q$منصة رقمية أطلقتها وزارة الاقتصاد والتخطيط لتمكين المستفيدين من الوصول إلى البيانات والمؤشرات الاقتصادية والاجتماعية الخاصة بالمملكة العربية السعودية ومناطقها المختلفة. تجمع المنصة بيانات من مصادر محلية ودولية موثوقة، وتعرضها باستخدام أدوات تحليل ورسوم بيانية تفاعلية تسهّل فهم الاتجاهات الاقتصادية والاجتماعية. ويمكن لرواد الأعمال والمبتكرين الاستفادة منها في دراسة الأسواق، وتحديد القطاعات الواعدة، وتحليل الخصائص الاقتصادية والديموغرافية للمناطق المستهدفة، ودعم القرارات المتعلقة بإطلاق المنتجات والخدمات الجديدة. كما يستفيد منها الباحثون والشركات الناشئة عند إعداد دراسات الجدوى وتحليل البيئة الاقتصادية، وتقديم بيانات موثوقة تدعم خطط الأعمال والعروض الاستثمارية.$q$,$q$https://datasaudi.sa/ar$q$,$q$https://datasaudi.sa/ar$q$,array[$q$بيانات اقتصادية$q$,$q$دراسات السوق$q$,$q$دعم اتخاذ القرار$q$]::text[],array[$q$tech$q$,$q$market$q$,$q$ip$q$]::text[],null,40),
  (41,$q$o7$q$,$q$أداة INSAIGHTS للتحليل بالذكاء الاصطناعي$q$,$q$أداة تحليل ذكية أطلقتها وزارة الاقتصاد والتخطيط ضمن منصة بيانات السعودية، وتستخدم تقنيات الذكاء الاصطناعي الوكيل لتمكين المستفيدين من استكشاف البيانات الوطنية وتحليلها باستخدام الأسئلة المباشرة. تعتمد الأداة على أكثر من 7,500 مؤشر اقتصادي واجتماعي، وتساعد المستخدمين على الوصول إلى تحليلات ومعلومات تدعم اتخاذ القرارات المبنية على البيانات. ويمكن لرواد الأعمال الاستفادة منها في دراسة الاتجاهات الاقتصادية، وتحليل القطاعات والأسواق المحتملة، وفهم المتغيرات التي قد تؤثر في فرص نجاح المشاريع الجديدة. كما توفر للباحثين والمبتكرين وسيلة لتسريع التحليل الأولي للبيانات، وتطوير فرضيات بحثية وتجارية تستند إلى مؤشرات رسمية.$q$,$q$https://datasaudi.sa/en/insaights$q$,$q$https://datasaudi.sa/en/insaights$q$,array[$q$تحليل البيانات$q$,$q$الذكاء الاصطناعي$q$,$q$أبحاث السوق$q$]::text[],array[$q$tech$q$,$q$market$q$,$q$ip$q$]::text[],null,41),
  (42,$q$o7$q$,$q$منصة راصد – RASED$q$,$q$منصة إلكترونية تفاعلية تقدمها وزارة الاقتصاد والتخطيط لمتابعة وتحليل مؤشرات الميزان التجاري وميزان المدفوعات للمملكة العربية السعودية ودول العالم. تتيح المنصة للمستفيدين استكشاف البيانات المتعلقة بالتجارة الدولية والتغيرات الاقتصادية المرتبطة بها، بما يسهم في فهم حركة التجارة والعلاقات الاقتصادية بين الدول. ويمكن لرواد الأعمال وأصحاب المشاريع الاستفادة من هذه البيانات عند دراسة فرص التوسع في الأسواق الدولية، وتحليل الاتجاهات التجارية، وتحديد الأسواق التي تستحق الدراسة بصورة أعمق. كما يمكن للباحثين والمبتكرين استخدامها لدعم الدراسات الاقتصادية المرتبطة بالمنتجات والخدمات الجديدة، وفهم البيئة التجارية التي قد تؤثر في جدوى المشاريع.$q$,$q$https://bi.mep.gov.sa/$q$,$q$https://bi.mep.gov.sa/$q$,array[$q$تحليل التجارة الدولية$q$,$q$دراسة الأسواق الخارجية$q$]::text[],array[$q$tech$q$,$q$market$q$]::text[],null,42),
  (43,$q$o8$q$,$q$البرنامج السعودي لمنح الابتكار – Saudi Innovation Grants Program (SIGP)$q$,$q$برنامج تمويلي تقدمه هيئة تنمية البحث والتطوير والابتكار بالتعاون مع البرنامج الوطني لتنمية تقنية المعلومات (NTDP)، لدعم الشركات الناشئة والمنشآت الصغيرة والمتوسطة في تطوير الابتكارات القائمة على البحث والتطوير وتحويلها إلى منتجات قابلة للتسويق. يستهدف البرنامج المشاريع المرتبطة بالأولويات الوطنية الأربع، وهي صحة الإنسان، واستدامة البيئة والاحتياجات الأساسية، والريادة في الطاقة والصناعة، واقتصاديات المستقبل. ويشمل الدعم تطوير إثبات المفهوم، واختبار النماذج الأولية، والتحقق من الجدوى التقنية والتجارية للابتكارات. ويساعد البرنامج الشركات على تقليل المخاطر المصاحبة لتطوير التقنيات الجديدة، وتسريع الانتقال من المراحل البحثية إلى التطبيقات العملية والفرص التجارية.$q$,$q$https://saudiminds.rdia.gov.sa/$q$,$q$https://saudiminds.rdia.gov.sa/$q$,array[$q$منح مالية$q$,$q$تطوير منتجات$q$,$q$إثبات المفهوم$q$,$q$تتجير الابتكارات$q$]::text[],array[$q$fund$q$,$q$prod$q$,$q$ip$q$]::text[],null,43),
  (44,$q$o8$q$,$q$منحة التطبيقات الأساسية – Baseload Applied Grant (BAG)$q$,$q$تندرج المنحة ضمن برنامج الأبحاث التطبيقية والتقنية السعودي، وتهدف إلى تحويل نتائج البحوث الأساسية إلى تطبيقات عملية من خلال تطوير نماذج إثبات المفهوم والتحقق من جدواها في المختبر. وتستهدف المشاريع البحثية التي وصلت إلى مستويات أولية من الجاهزية التقنية، وتحتاج إلى تجارب إضافية لإثبات إمكانية تطبيق النتائج خارج الإطار النظري. توفر المنحة تمويلًا يصل إلى 1.6 مليون ريال لمدة تصل إلى 36 شهرًا، وفق الشروط المعلنة. وتعد مناسبة للباحثين الذين توصلوا إلى نتائج أو تقنيات واعدة، ويرغبون في تطويرها نحو تطبيقات ذات احتياجات واضحة، تمهيدًا للانتقال إلى مراحل التطوير التقني أو التسويق التجاري.$q$,$q$https://saudiminds.rdia.gov.sa/account/grants-info/3?nationalPrioritiesId=1$q$,$q$https://saudiminds.rdia.gov.sa/account/grants-info/3?nationalPrioritiesId=1$q$,array[$q$تمويل الأبحاث التطبيقية$q$,$q$تطوير إثبات المفهوم$q$]::text[],array[$q$fund$q$,$q$prod$q$,$q$ip$q$]::text[],null,44),
  (45,$q$o8$q$,$q$منحة التطوير التقني – Technology Development Grant (TDG)$q$,$q$تهدف المنحة إلى تسريع تطوير التقنيات الواعدة التي سبق إثبات جدواها الأولية، وتمتلك فرصًا للتطبيق التجاري في المجالات ذات الأولوية الوطنية. تدعم المنحة تطوير النماذج التقنية واختبارها والتحقق من أدائها في البيئات المختبرية والتشغيلية، بما يساعد على الانتقال من مرحلة إثبات المفهوم إلى تقنيات أكثر جاهزية للاستخدام. ويصل التمويل إلى 10 ملايين ريال لمدة تصل إلى 36 شهرًا وفق الشروط المعلنة. ويمكن للجامعات والمراكز البحثية والجهات المؤهلة في القطاع الخاص التقدم بالمشاريع، بما يتيح فرصًا للتعاون بين الباحثين والشركات لتطوير التقنيات الجديدة وتحسين جاهزيتها للتطبيق التجاري ونقل المعرفة إلى السوق.$q$,$q$https://saudiminds.rdia.gov.sa/account/grants-info/4?nationalPrioritiesId=1$q$,$q$https://saudiminds.rdia.gov.sa/account/grants-info/4?nationalPrioritiesId=1$q$,array[$q$تمويل تطوير التقنيات$q$,$q$اختبار النماذج$q$,$q$التحقق التشغيلي$q$]::text[],array[$q$fund$q$,$q$prod$q$]::text[],null,45),
  (46,$q$o8$q$,$q$منحة الابتكار بين القطاع الأكاديمي والصناعة – Academia-Industry Innovation Grant (AIIG)$q$,$q$تدعم المنحة تطوير التقنيات من خلال الشراكات بين الجامعات والمؤسسات البحثية والقطاع الخاص، بهدف معالجة احتياجات واضحة في السوق وتحويل المخرجات البحثية إلى تطبيقات قابلة للتسويق. وتركز على المشاريع التي تجمع بين المعرفة العلمية والخبرة الصناعية، وتستهدف مستويات الجاهزية التقنية التي تسمح بالتطوير والتحقق من الأداء في بيئات تطبيقية. وتوفر تمويلًا قد يصل إلى 12 مليون ريال لمدة تصل إلى 36 شهرًا، وفق الشروط المعلنة. وتساعد المنحة الباحثين والشركات على العمل المشترك في تطوير المنتجات، وتقليل الفجوة بين نتائج الأبحاث ومتطلبات السوق، وتهيئة مسارات لنقل التقنية واستثمار الملكية الفكرية الناتجة عن المشاريع المشتركة.$q$,$q$https://saudiminds.rdia.gov.sa/account/grants-info/5?nationalPrioritiesId=1$q$,$q$https://saudiminds.rdia.gov.sa/account/grants-info/5?nationalPrioritiesId=1$q$,array[$q$شراكات بحثية صناعية$q$,$q$تمويل مشترك$q$,$q$نقل التقنية$q$]::text[],array[$q$fund$q$,$q$train$q$,$q$market$q$,$q$ip$q$]::text[],null,46),
  (47,$q$o8$q$,$q$مبادرة حوافز تتجير الملكية الفكرية – IP Commercialization Incentives Initiative$q$,$q$مبادرة وطنية تهدف إلى مساعدة الباحثين والمبتكرين والشركات على تطوير ملكيتهم الفكرية وحمايتها وتحويلها إلى فرص تجارية. تستهدف المبادرة الجامعات والمراكز البحثية والمستشفيات والأفراد والقطاع الخاص، وتركز على الابتكارات المرتبطة بالأولويات الوطنية للبحث والتطوير والابتكار. وتشمل حزمة من الحوافز والخدمات المتخصصة، منها دعم تكاليف تسجيل الملكية الفكرية، وقسائم نقل التقنية، والاستشارات المتعلقة بدراسات الجدوى واستراتيجيات الحماية والتسويق. كما تتضمن المبادرة إطارًا للحوافز الضريبية المرتبطة بالدخل الناتج عن الملكية الفكرية. وتساعد هذه الخدمات أصحاب البراءات والتقنيات الواعدة على تقييم فرص الاستثمار والترخيص، واستكمال المتطلبات اللازمة لنقل التقنيات إلى السوق.$q$,$q$https://rdia.gov.sa/programs/infrastructure/ip-commercialization-incentives-initiative/$q$,$q$https://rdia.gov.sa/programs/infrastructure/ip-commercialization-incentives-initiative/$q$,array[$q$حماية الملكية الفكرية$q$,$q$تطوير الأعمال$q$,$q$تتجير التقنيات$q$]::text[],array[$q$ip$q$]::text[],null,47),
  (48,$q$o8$q$,$q$دعم تسجيل الملكية الفكرية – IP Filing Subsidy$q$,$q$خدمة ضمن مبادرة حوافز تتجير الملكية الفكرية، تقدم دعمًا ماليًا لتغطية تكاليف مختارة مرتبطة بإيداع طلبات براءات الاختراع. تستهدف المبتكرين والباحثين والجهات التي تمتلك تقنيات ذات إمكانات تجارية، وتحتاج إلى استكمال إجراءات حماية الملكية الفكرية قبل عرضها على المستثمرين أو البدء في مفاوضات الترخيص. ويمكن أن يساعد الدعم في تقليل الأعباء المالية المرتبطة بإجراءات الحماية، خاصة للمشاريع في مراحلها المبكرة. وتشير الهيئة إلى أن الدعم يبدأ بصورة مسبقة، مع توجه لاحق لتطبيق آلية الاسترداد. وتخضع الاستفادة لمعايير اختيار وتكاليف مؤهلة تحددها المبادرة، ولا تعني تغطية جميع رسوم إيداع البراءات تلقائيًا.$q$,$q$https://rdia.gov.sa/programs/infrastructure/ip-commercialization-incentives-initiative/$q$,$q$https://rdia.gov.sa/programs/infrastructure/ip-commercialization-incentives-initiative/$q$,array[$q$مساهمة مالية في تكاليف حماية الملكية الفكرية$q$]::text[],array[$q$fund$q$,$q$ip$q$]::text[],null,48),
  (49,$q$o8$q$,$q$قسائم نقل التقنية – Technology Transfer Voucher$q$,$q$توفر هذه الخدمة للمبتكرين والباحثين والشركات المؤهلة قسائم للاستفادة من خدمات خبراء متخصصين في تطوير التقنيات وتحويلها إلى فرص تجارية. وتشمل الخدمات دراسات الجدوى الفنية والاقتصادية وتقييم الأثر، ووضع استراتيجيات حماية الملكية الفكرية، وتحليل المنافسة التقنية، وتطوير نماذج الأعمال وخطط دخول السوق، وإعداد استراتيجيات الترخيص. وتهدف القسائم إلى توفير دعم عملي يتجاوز الاستشارات العامة، بما يساعد أصحاب الابتكارات على معالجة الفجوات التي تعيق التتجير. وتعد مناسبة للمشاريع التي تمتلك براءة اختراع أو تقنية واعدة، وتحتاج إلى استكمال الجوانب التجارية والقانونية والفنية قبل التفاوض مع مستثمر أو شريك صناعي.$q$,$q$https://rdia.gov.sa/programs/infrastructure/ip-commercialization-incentives-initiative/$q$,$q$https://rdia.gov.sa/programs/infrastructure/ip-commercialization-incentives-initiative/$q$,array[$q$خدمات تتجير متخصصة$q$,$q$جدوى اقتصادية$q$,$q$استشارات قانونية$q$]::text[],array[$q$mentor$q$,$q$ip$q$]::text[],null,49),
  (50,$q$o8$q$,$q$الاحتضان والشراكات والابتكار المفتوح$q$,$q$مبادرة وطنية تربط الشركات الناشئة والمنشآت الصغيرة والمتوسطة ورواد الأعمال بالجهات الفاعلة في منظومة البحث والتطوير والابتكار داخل المملكة وخارجها. تستهدف المبادرة المشاريع القائمة على البحث والتطوير، وتسعى إلى تسهيل حصولها على الخدمات والممكنات وفرص التعاون اللازمة لتطوير أعمالها. وتضم شبكة من الشركاء تشمل الجامعات والمراكز البحثية والجهات الحكومية والشركات ومؤسسات الاستثمار والابتكار. وتساعد المبادرة أصحاب التقنيات المبتكرة على بناء علاقات مع الجهات القادرة على دعم تطوير المنتجات واختبارها وتوسيع نطاق استخدامها. كما تشجع التعاون لمعالجة التحديات الوطنية والعالمية من خلال الابتكار والبحث والتطوير.$q$,$q$https://rdia.gov.sa/en/programs/infrastructure/national-rdi-virtual-cluster/$q$,$q$https://rdia.gov.sa/en/programs/infrastructure/national-rdi-virtual-cluster/$q$,array[$q$تمكين الشركات الناشئة$q$,$q$تطوير الأعمال$q$]::text[],array[$q$incub$q$,$q$market$q$]::text[],null,50),
  (51,$q$o8$q$,$q$برنامج الابتكار المشترك في الذكاء الاصطناعي – AI Co-Innovation$q$,$q$برنامج يستهدف الباحثين ورواد الأعمال والشركات الناشئة والمتخصصين الصناعيين لتطوير حلول قائمة على الذكاء الاصطناعي تعالج تحديات واقعية في قطاعات الطاقة والصناعة والخدمات اللوجستية. يشمل البرنامج تحديد التحديات وتطوير الأفكار والنماذج الأولية، والتدريب المتخصص بالتعاون مع CNTXT، والإرشاد من خبراء الذكاء الاصطناعي والقطاع الصناعي. كما يتيح للمشاركين الوصول إلى أدوات وبيانات تقنية، والمنافسة على فرص تمويل واحتضان، وعرض حلولهم أمام المستثمرين والخبراء. ويتناول تحديات مثل أتمتة الحفر، وتحليل العمليات، والمحاكاة، وتحسين الخدمات اللوجستية. ويعد مناسبًا للفرق التي تمتلك خبرات تقنية وتسعى إلى اختبار حلولها ضمن تطبيقات صناعية فعلية.$q$,$q$https://rdia.gov.sa/en/programs/infrastructure/ai-co-innovation-unleash-your-ai-potential-build-real-world-solutions$q$,$q$https://rdia.gov.sa/en/programs/infrastructure/ai-co-innovation-unleash-your-ai-potential-build-real-world-solutions$q$,array[$q$تطوير نماذج أولية$q$,$q$تدريب$q$,$q$احتضان$q$,$q$فرص تمويل$q$]::text[],array[$q$fund$q$,$q$incub$q$,$q$train$q$,$q$prod$q$,$q$tech$q$,$q$market$q$]::text[],null,51),
  (52,$q$o8$q$,$q$التجمع الوطني للحوسبة الكمية – National Quantum Cluster$q$,$q$مبادرة وطنية تنفذها الهيئة بالشراكة مع أرامكو لدعم منظومة البحث والتطوير والابتكار في تقنيات الحوسبة الكمية. تستهدف الباحثين والمهندسين والطلاب والأكاديميين ورواد الأعمال والشركات الناشئة والمتخصصين في القطاع الصناعي. وتعمل المبادرة على ربط الجهات الأكاديمية والصناعية والحكومية، وتطوير القدرات البحثية والمهارات المتخصصة، وتسهيل الوصول إلى منصات وتقنيات الحوسبة الكمية المتقدمة. كما تشمل دعم ريادة الأعمال وتأسيس المشاريع المرتبطة بالتقنيات الكمية، وتطوير فرص التعاون التجريبي بين الجهات المختلفة. ويمكن أن يستفيد منها المبتكرون الذين يعملون على تطبيقات الحوسبة الكمية أو التقنيات المرتبطة بها، ويرغبون في تطوير مشاريعهم ضمن منظومة متخصصة.$q$,$q$https://rdia.gov.sa/programs/infrastructure/national-quantum/$q$,$q$https://rdia.gov.sa/programs/infrastructure/national-quantum/$q$,array[$q$البحث والتطوير$q$,$q$الوصول إلى البنية التحتية$q$,$q$الشراكات التقنية$q$]::text[],array[$q$tech$q$,$q$space$q$,$q$market$q$,$q$ip$q$]::text[],null,52),
  (53,$q$o8$q$,$q$الوصول المفتوح للبنية التحتية البحثية – Open Access$q$,$q$خدمة وطنية تتيح للباحثين والمبتكرين والجهات البحثية والشركات التعرف على المختبرات والأجهزة والبنية التحتية البحثية المتوفرة لدى الجامعات ومراكز الأبحاث في المملكة، وتقديم طلبات للاستفادة منها وفق الضوابط المنظمة. تهدف المبادرة إلى تعزيز استخدام التجهيزات البحثية القائمة وتسهيل التعاون بين الجهات المختلفة، بدلًا من الحاجة إلى شراء الأجهزة أو إنشاء مختبرات جديدة لكل مشروع. ويمكن للمبتكرين الاستفادة منها لتنفيذ التجارب العلمية، واختبار المواد والتقنيات، والتحقق من أداء النماذج الأولية، وتطوير المنتجات الجديدة. وتضم المنصة جهات بحثية متعددة، منها جامعة القصيم وجامعة الملك عبدالله للعلوم والتقنية ومدينة الملك عبدالعزيز للعلوم والتقنية.$q$,$q$https://rdia.gov.sa/programs/infrastructure/open-access2/$q$,$q$https://rdia.gov.sa/programs/infrastructure/open-access2/$q$,array[$q$مختبرات$q$,$q$أجهزة بحثية$q$,$q$تجارب$q$,$q$تطوير النماذج الأولية$q$]::text[],array[$q$prod$q$,$q$space$q$,$q$market$q$,$q$ip$q$]::text[],null,53),
  (54,$q$o8$q$,$q$خدمة تصاريح مواد البحث والتطوير والابتكار$q$,$q$خدمة إلكترونية تقدمها الهيئة لتسهيل حصول الجهات العاملة في البحث والتطوير والابتكار ومورديها على التصاريح اللازمة لاستيراد المواد البحثية إلى المملكة. تستهدف الجامعات والمراكز البحثية والشركات والجهات التي تحتاج إلى مواد متخصصة لتنفيذ التجارب أو تطوير التقنيات والمنتجات. وتوفر الخدمة آلية لتقديم الطلبات ومتابعتها إلكترونيًا، إلى جانب أدلة إرشادية توضح متطلبات التسجيل والإجراءات لكل فئة من المستفيدين. وتساعد على تقليل العقبات الإجرائية التي قد تواجه الباحثين والشركات خلال توفير المواد اللازمة للتجارب، بما يسهم في استمرارية الأنشطة البحثية والتطويرية وفق الاشتراطات والأنظمة المعمول بها.$q$,$q$https://rdia.gov.sa/programs/infrastructure/rdi-materials/$q$,$q$https://rdia.gov.sa/programs/infrastructure/rdi-materials/$q$,array[$q$تسهيل الإجراءات التنظيمية$q$,$q$استيراد المواد البحثية$q$]::text[],array[$q$ip$q$]::text[],null,54),
  (55,$q$o8$q$,$q$تحدي الفضاء – Space Challenges$q$,$q$مبادرة بحثية تهدف إلى تحفيز الابتكار من خلال الاستفادة من البيئة الفضائية في المدار الأرضي المنخفض لتطوير تجارب وحلول علمية مرتبطة بالأولويات الوطنية. يتيح التحدي للباحثين والمبتكرين طرح مشاريع تستفيد من الخصائص الفريدة للفضاء، أو من البيانات والتقنيات الفضائية، لمعالجة قضايا مرتبطة بالصحة والاستدامة والطاقة والبنية التحتية. وتشمل مجالات التحدي مراقبة الأمراض وجودة الهواء، واستخدام الذكاء الاصطناعي وبيانات مراقبة الأرض للاستدامة البيئية، وتحسين الطاقة الشمسية وكفاءة الشبكات الذكية، وتطوير إدارة البنية التحتية. ويمثل البرنامج فرصة للباحثين وأصحاب التقنيات المتقدمة لتطوير تطبيقات ذات استخدامات علمية واقتصادية محتملة.$q$,$q$https://rdia.gov.sa/programs/infrastructure/space-challenges/$q$,$q$https://rdia.gov.sa/programs/infrastructure/space-challenges/$q$,array[$q$تحديات بحثية$q$,$q$تطوير حلول علمية وتقنية$q$]::text[],array[$q$prod$q$,$q$compete$q$,$q$ip$q$]::text[],null,55),
  (56,$q$o9$q$,$q$بوابة منظومة الابتكار التجاري «فكرة»$q$,$q$بوابة إلكترونية تهدف إلى تمكين المبتكرين والشركات الابتكارية من الوصول إلى الجهات والخدمات التي تساعدهم على تطوير أفكارهم وتحويلها إلى مشاريع تجارية. تجمع البوابة أكثر من 100 جهة حكومية وخاصة وغير ربحية، وتعرض أكثر من 200 خدمة في مجالات متعددة، تشمل تطوير المنتجات، والاحتضان، والتمويل، والاستشارات، والتقنيات الصاعدة. وتتيح للمستفيدين استكشاف الخدمات المناسبة لمراحل مشاريعهم والتواصل مع الجهات المقدمة لها. كما تشمل مكتبة معرفية، وفعاليات متخصصة، وقسمًا لإبراز الشركات الابتكارية الجاهزة للاستثمار. وتعد البوابة مناسبة للمبتكرين الذين يحتاجون إلى التعرف على الممكنات المتاحة وتحديد الجهات المناسبة لدعم مشاريعهم.$q$,$q$https://monshaat.gov.sa/ar/node/12827$q$,$q$https://monshaat.gov.sa/ar/node/12827$q$,array[$q$خدمات الابتكار$q$,$q$الربط بالجهات الداعمة$q$,$q$فرص الاستثمار$q$]::text[],array[$q$invest$q$,$q$market$q$]::text[],null,56),
  (57,$q$o9$q$,$q$مركز الابتكار – Innovation Center$q$,$q$مراكز متخصصة في التقنيات الصاعدة توفر خدمات متكاملة للمبتكرين والشركات الناشئة، من مرحلة بناء المنتج الأولي حتى الوصول إلى السوق. تقدم المراكز خدمات الدعم التقني، والنمذجة الأولية، والاستشارات والإرشاد، والاحتضان، إضافة إلى المعسكرات والورش والفعاليات المتخصصة. وتشمل مرافقها معمل النمذجة، ومعمل الأمن السيبراني، واستوديو تجربة المستخدم وواجهة المستخدم (UI/UX). وتركز خدماتها على مجالات الذكاء الاصطناعي وعلوم البيانات وإنترنت الأشياء والأمن السيبراني وغيرها من التقنيات. ويمكن للمبتكرين الاستفادة من هذه المرافق لتطوير الحلول التقنية واختبارها، وتحسين جاهزية منتجاتهم قبل طرحها في السوق.$q$,$q$https://innovationcenter.monshaat.gov.sa/$q$,$q$https://innovationcenter.monshaat.gov.sa/$q$,array[$q$تطوير منتجات$q$,$q$نمذجة أولية$q$,$q$احتضان$q$,$q$استشارات تقنية$q$]::text[],array[$q$mentor$q$,$q$incub$q$,$q$prod$q$]::text[],null,57),
  (58,$q$o9$q$,$q$برنامج رواد الابتكار$q$,$q$برنامج مكثف يقدمه مركز الابتكار التابع لمنشآت لتمكين الشركات الناشئة المبتكرة والمنشآت القائمة التي تمتلك فرصًا للتطور والنمو. يمتد البرنامج لمدة شهرين، ويجمع بين الإرشاد المباشر والتقييم المتخصص للأداء من خلال خبراء في الابتكار وريادة الأعمال. ويساعد المشاركين على دراسة التحديات التي تواجه مشاريعهم، وتحسين المنتجات ونماذج الأعمال، وتحديد الفرص المتاحة في السوق. ويركز البرنامج على تطوير قدرة الشركات على الاستفادة من التقنيات الحديثة وتحويلها إلى قيمة تجارية. ويعد مناسبًا للشركات التي تجاوزت مرحلة الفكرة وتحتاج إلى دعم منظم لتطوير عملياتها وتحسين جاهزيتها للنمو.$q$,$q$https://innovationcenter.monshaat.gov.sa/programs/innovation-pioneers$q$,$q$https://innovationcenter.monshaat.gov.sa/programs/innovation-pioneers$q$,array[$q$إرشاد$q$,$q$تطوير شركات ابتكارية$q$,$q$تقييم أداء$q$]::text[],array[$q$mentor$q$,$q$prod$q$,$q$ip$q$]::text[],null,58),
  (59,$q$o9$q$,$q$تحديات الابتكار – Innovation Challenges$q$,$q$خدمة يقدمها مركز الابتكار لتشجيع المبتكرين ورواد الأعمال وأصحاب المهارات التقنية على تطوير حلول للتحديات التي تواجه الشركات والجهات الحكومية. تقوم الفكرة على عرض مشكلات واحتياجات فعلية، وإتاحة الفرصة للمشاركين لاقتراح حلول مبتكرة وتطويرها بما يتناسب مع متطلبات الجهات المستفيدة. وتساعد التحديات المشاركين على فهم احتياجات العملاء المحتملين، وتوجيه جهود تطوير المنتجات نحو فرص ذات تطبيق عملي. كما تتيح للمبتكرين العمل على أفكار قد تتحول إلى منتجات أو شركات ناشئة. وتختلف موضوعات التحديات ومتطلبات المشاركة بحسب الجهة الشريكة والبرنامج المعلن.$q$,$q$https://monshaat.gov.sa/ar/Challenges$q$,$q$https://monshaat.gov.sa/ar/Challenges$q$,array[$q$تحديات$q$,$q$تطوير حلول$q$,$q$دعم واستشارات$q$]::text[],array[$q$mentor$q$,$q$prod$q$,$q$compete$q$]::text[],null,59),
  (60,$q$o9$q$,$q$معسكرات الابتكار – Innovation Bootcamps$q$,$q$معسكرات تدريبية مكثفة ينظمها مركز الابتكار لتنمية المهارات التقنية والريادية لدى المبتكرين ورواد الأعمال. تتراوح مدة المعسكرات بين يومين وسبعة أيام، وتتناول موضوعات متخصصة في التقنيات الحديثة أو القطاعات الاقتصادية أو تطوير المنتجات التقنية. ويقدم المحتوى خبراء ومتخصصون، مع التركيز على التطبيقات العملية التي تساعد المشاركين على اكتساب مهارات يمكن توظيفها في مشاريعهم. ويمكن لأصحاب الأفكار الاستفادة من المعسكرات لفهم التقنيات المناسبة لمشاريعهم، وتطوير قدراتهم في تصميم الحلول واختبارها، والتعرف على متطلبات تحويل الأفكار إلى منتجات قابلة للتطبيق. وتختلف الموضوعات ومواعيد التسجيل بحسب المعسكر المعلن.$q$,$q$https://academy.monshaat.gov.sa/local/course/enrol.php?id=1614$q$,$q$https://academy.monshaat.gov.sa/local/course/enrol.php?id=1614$q$,array[$q$تدريب تطبيقي$q$,$q$تطوير منتجات تقنية$q$,$q$بناء مهارات$q$]::text[],array[$q$train$q$,$q$prod$q$]::text[],null,60),
  (61,$q$o9$q$,$q$برنامج الشركات الناشئة الجامعية$q$,$q$برنامج يستهدف تحويل الأفكار الابتكارية ومشاريع التخرج والاختراعات الجامعية إلى شركات ناشئة قابلة للنمو. يقدم البرنامج بالتعاون مع الجامعات مجموعة من المعسكرات والبرامج الإرشادية والتدريبية التي تساعد الطلاب وأعضاء هيئة التدريس وحديثي التخرج على تطوير أفكارهم وبناء نماذج أعمال قابلة للتطبيق. وتشمل خدماته تطوير النماذج الأولية، والاستشارات الريادية، والتدريب، وتسهيل الوصول إلى فرص التمويل والاستثمار. ويستهدف منسوبي الجامعات والخريجين خلال السنوات الثلاث الأولى بعد التخرج، وفق شروط كل مسار. ويتيح للفرق البحثية والطلابية فرصة استكمال تطوير مشاريعها والانتقال بها من البيئة الأكاديمية إلى السوق.$q$,$q$https://www.monshaat.gov.sa/ar/UniStartups-Dev$q$,$q$https://www.monshaat.gov.sa/ar/UniStartups-Dev$q$,array[$q$تتجير مشاريع التخرج$q$,$q$تطوير أفكار$q$,$q$احتضان$q$,$q$تمويل$q$]::text[],array[$q$fund$q$,$q$incub$q$,$q$prod$q$,$q$ip$q$]::text[],null,61),
  (62,$q$o9$q$,$q$برنامج مسرعات الأعمال$q$,$q$برنامج تقدمه منشآت بالشراكة مع جهات من القطاعين العام والخاص لدعم الشركات الناشئة وتسريع نموها خلال فترة تتراوح بين ثلاثة وستة أشهر. يوفر البرنامج خدمات تطوير الأعمال والتدريب والاستشارات والإرشاد، ومساحات عمل مجهزة، إلى جانب فرص التواصل مع المستثمرين والشركاء المحتملين. وقد تتضمن بعض المسرعات منحًا مالية وفرصًا استثمارية بحسب المسار المعلن. ويستهدف أصحاب الشركات الناشئة والمشاريع التي تمتلك نماذج عمل أو منتجات أولية، ويرغبون في تحسين جاهزيتها التجارية والتوسع في السوق. وتختلف القطاعات المستهدفة ومتطلبات القبول بحسب المسرعات التي تطلقها منشآت بالتعاون مع شركائها.$q$,$q$https://monshaat.gov.sa/ar/acc$q$,$q$https://monshaat.gov.sa/ar/acc$q$,array[$q$تسريع نمو$q$,$q$منح مالية بحسب المسرعة$q$,$q$تدريب$q$,$q$استثمار$q$]::text[],array[$q$fund$q$,$q$invest$q$,$q$incub$q$,$q$train$q$]::text[],null,62),
  (63,$q$o9$q$,$q$مجمعات الشركات الناشئة – Startup Hubs$q$,$q$توفر مجمعات الشركات الناشئة بيئات عمل مشتركة ومكاتب ومرافق خدمية تدعم رواد الأعمال والشركات في المراحل المبكرة من تأسيس المشاريع ونموها. وتقدم المجمعات برامج متنوعة تشمل التدريب، وورش العمل، والجلسات الاستشارية والإرشادية، والمعسكرات، واللقاءات مع الشركات الكبرى والجامعات والمستثمرين. كما تتيح للمستفيدين العمل ضمن مجتمعات ريادية تساعد على تبادل الخبرات وبناء العلاقات المهنية والتجارية. ويمكن للمبتكرين الاستفادة من هذه المجمعات لتطوير مشاريعهم وإدارة أعمالهم، والحصول على الخدمات المناسبة لمرحلة نمو المنشأة. وتختلف رسوم استئجار المكاتب ومساحات العمل بحسب الموقع والمساحة والمدة.$q$,$q$https://monshaat.gov.sa/ar/hubs$q$,$q$https://monshaat.gov.sa/ar/hubs$q$,array[$q$استشارات$q$,$q$إرشاد$q$,$q$تحليل احتياجات$q$,$q$ربط بالجهات الداعمة$q$]::text[],array[$q$mentor$q$,$q$tech$q$]::text[],null,63),
  (64,$q$o9$q$,$q$تطبيق نوافذ منشآت$q$,$q$تطبيق رقمي يتيح لرواد الأعمال وأصحاب المنشآت الصغيرة والمتوسطة الوصول إلى مجموعة واسعة من خدمات منشآت من خلال قناة موحدة. ويمكن للمستفيدين حجز الجلسات الاستشارية والإرشادية مع خبراء متخصصين في مجالات متعددة تشمل التسويق والمبيعات والإدارة والمالية والجوانب القانونية والتقنية والابتكار. كما يوفر التطبيق إمكانية استعراض الخدمات والبرامج المتاحة والاستفادة منها دون الحاجة إلى زيارة مراكز الدعم حضوريًا. وتتيح الخدمة الحصول على جلسات مدعومة بالكامل، مع إمكان الاستفادة من عدد من الجلسات شهريًا بحسب الضوابط. ويعد التطبيق مناسبًا للمبتكرين الذين يحتاجون إلى توجيه متخصص خلال تأسيس مشاريعهم أو تطوير منتجاتهم.$q$,$q$https://www.monshaat.gov.sa/ar/apps$q$,$q$https://www.monshaat.gov.sa/ar/apps$q$,array[$q$استشارات وإرشاد عن بُعد$q$,$q$الوصول للخدمات$q$]::text[],array[$q$mentor$q$]::text[],null,64),
  (65,$q$o9$q$,$q$خدمات التدريب – أكاديمية منشآت$q$,$q$منصة تدريبية تقدم برامج ودورات مجانية حضورية وافتراضية تهدف إلى تنمية قدرات رواد الأعمال وأصحاب المنشآت الصغيرة والمتوسطة في الجوانب الإدارية والمالية والفنية والتجارية. تشمل الموضوعات تطوير نماذج الأعمال، وإدارة المشاريع، والتسويق، والتخطيط المالي، وإدارة الموارد البشرية، وغيرها من المهارات التي يحتاج إليها أصحاب المشاريع في مراحل التأسيس والنمو. ويمكن للمبتكرين الاستفادة من هذه البرامج لاكتساب المهارات اللازمة لتحويل الأفكار التقنية إلى مشاريع تجارية وإدارة عملياتها. وتوفر الأكاديمية برامج تعليمية يمكن الوصول إليها إلكترونيًا، بالإضافة إلى ورش تدريبية حضورية وفق الجداول المعلنة، مع شهادات للمستفيدين المستوفين للمتطلبات.$q$,$q$https://academy.monshaat.gov.sa/$q$,$q$https://academy.monshaat.gov.sa/$q$,array[$q$تدريب$q$,$q$تطوير مهارات ريادة الأعمال$q$,$q$إدارة المشاريع$q$]::text[],array[$q$train$q$]::text[],null,65),
  (66,$q$o9$q$,$q$برنامج تحفيز رائدات الأعمال$q$,$q$برنامج متخصص يهدف إلى تشجيع مشاركة المرأة في ريادة الأعمال وتمكين رائدات الأعمال من تأسيس مشاريعهن وتطويرها. يقدم البرنامج مجموعة من المعسكرات والورش واللقاءات التعريفية بالبرامج والخدمات المتاحة لدى منشآت، إضافة إلى توجيه المستفيدات نحو الفرص المناسبة في القطاعات الاقتصادية الواعدة. ويساعد على تطوير المهارات اللازمة لإدارة المشاريع التجارية، والتعرف على التحديات التنظيمية والتشغيلية والتسويقية، والاستفادة من الخدمات الاستشارية والتدريبية. ويستهدف رائدات الأعمال والمهتمات بريادة الأعمال من السعوديات أو من يعاملن معاملتهن، ممن تجاوزن سن الثامنة عشرة، وفق شروط البرامج والفعاليات المعلنة.$q$,$q$https://monshaat.gov.sa/ar/node/12845$q$,$q$https://monshaat.gov.sa/ar/node/12845$q$,array[$q$تدريب$q$,$q$إرشاد$q$,$q$تطوير أعمال$q$,$q$تمكين الوصول للأسواق$q$]::text[],array[$q$mentor$q$,$q$train$q$,$q$market$q$]::text[],null,66),
  (67,$q$o9$q$,$q$مبادرة استرداد$q$,$q$مبادرة وطنية أطلقتها منشآت لدعم المنشآت متناهية الصغر والصغيرة والمتوسطة الجديدة، من خلال إعادة رسوم حكومية مؤهلة سبق أن دفعتها المنشآت خلال مراحل تأسيسها وتشغيلها. وتغطي النسخة الثانية الأعوام المالية من 2024 إلى 2028، وتهدف إلى تخفيف الأعباء المالية على رواد الأعمال وتعزيز قدرة منشآتهم على الاستمرار والنمو خلال السنوات الأولى. ويمكن للشركات الناشئة الاستفادة من المبادرة لتقليل بعض التكاليف المرتبطة بالإجراءات الحكومية، وتوجيه جزء أكبر من مواردها إلى تطوير المنتجات والعمليات التشغيلية. وتخضع الاستفادة لمتطلبات محددة تتعلق بأهلية المنشأة ونوع الرسوم والفترات المشمولة وآلية التقديم.$q$,$q$https://estrdad.monshaat.gov.sa/home$q$,$q$https://estrdad.monshaat.gov.sa/home$q$,array[$q$استرداد رسوم حكومية$q$,$q$تخفيف تكاليف التأسيس والتشغيل$q$]::text[],array[$q$fund$q$,$q$incub$q$]::text[],null,67),
  (68,$q$o9$q$,$q$مزايا – الخدمات المخفّضة$q$,$q$منصة تتيح للمنشآت الصغيرة والمتوسطة الحصول على خدمات تجارية وتشغيلية بأسعار تنافسية، من خلال التعاون مع مقدمي خدمات من القطاع الخاص. تشمل الخدمات المعروضة مجالات مثل المحاسبة، والتأمين الصحي، والشحن والتوصيل، وغيرها من الاحتياجات التشغيلية التي تواجه المنشآت خلال التأسيس والنمو. ويمكن للشركات الناشئة الاستفادة من العروض لتخفيض بعض التكاليف وتحسين قدرتها على إدارة الموارد. كما تتيح المنصة لمقدمي الخدمات عرض منتجاتهم والوصول إلى عملاء جدد من المنشآت الصغيرة والمتوسطة. وتتفاوت مستويات الخصم والدعم بحسب الخدمة والمزود، وقد تكون بعض الخدمات مدعومة جزئيًا أو كليًا.$q$,$q$https://mazaya.monshaat.gov.sa/$q$,$q$https://mazaya.monshaat.gov.sa/$q$,array[$q$خدمات تجارية مخفضة$q$,$q$تقليل التكاليف$q$,$q$تمكين المنشآت$q$]::text[],array[$q$fund$q$,$q$market$q$]::text[],null,68),
  (69,$q$o9$q$,$q$جدير – خدمة التأهيل المسبق$q$,$q$خدمة إلكترونية تهدف إلى تأهيل المنشآت متناهية الصغر والصغيرة والمتوسطة وإثبات جاهزيتها لتقديم المنتجات والخدمات للجهات الحكومية والشركات الكبرى في القطاع الخاص. تتضمن عملية التأهيل مراجعة البيانات النظامية والتشغيلية للمنشأة والتحقق من استيفائها للمتطلبات، ثم إصدار شهادة تأهيل تساعد على تعزيز ثقة العملاء المحتملين بقدراتها. ويمكن للشركات الناشئة التي طورت منتجات أو خدمات جاهزة للتسويق الاستفادة من الخدمة في تحسين فرص الوصول إلى المشتريات والعقود المؤسسية. وتستهدف الخدمة المنشآت القائمة في جميع القطاعات، مع اشتراط استكمال البيانات النظامية وإصدار شهادة حجم المنشأة واستيفاء متطلبات النشاط المسجل.$q$,$q$https://jadeer-s.monshaat.gov.sa/$q$,$q$https://jadeer-s.monshaat.gov.sa/$q$,array[$q$تأهيل الشركات$q$,$q$فرص المشتريات$q$,$q$الوصول إلى العملاء المؤسسيين$q$]::text[],array[$q$train$q$,$q$market$q$]::text[],null,69),
  (70,$q$o9$q$,$q$برنامج طموح – خدمات المنشآت متسارعة النمو$q$,$q$برنامج مخصص للمنشآت الصغيرة والمتوسطة التي حققت نموًا متسارعًا وترغب في تطوير قدراتها والتوسع في الأسواق المحلية والدولية. يوفر البرنامج منظومة من الخدمات المتخصصة التي تشمل تحليل وضع المنشأة وتشخيص احتياجاتها، وتصميم خطط النمو، وربطها بمقدمي الخدمات والخبرات المناسبة. كما يساعد على تسهيل الوصول إلى التمويل والمعرفة والأسواق، وتحسين الأداء التشغيلي والإداري. ويستهدف المنشآت السعودية التي حققت نموًا بنسبة 20% أو أكثر في الإيرادات أو أعداد الموظفين لمدة ثلاث سنوات متتابعة، وفق المعايير المنشورة. ويعد مناسبًا للشركات التقنية والابتكارية التي تجاوزت مراحل التأسيس وبدأت تحقق نتائج تجارية واضحة.$q$,$q$https://tomoh.monshaat.gov.sa/$q$,$q$https://tomoh.monshaat.gov.sa/$q$,array[$q$تسريع نمو$q$,$q$الوصول إلى التمويل$q$,$q$الأسواق$q$,$q$الخبرات$q$]::text[],array[$q$fund$q$,$q$mentor$q$,$q$incub$q$,$q$market$q$]::text[],null,70),
  (71,$q$o9$q$,$q$شهادة حجم المنشأة$q$,$q$خدمة إلكترونية مجانية تتيح للمنشآت إصدار شهادة رسمية تثبت تصنيفها ضمن المنشآت متناهية الصغر أو الصغيرة أو المتوسطة وفق معايير منشآت. تساعد الشهادة أصحاب المشاريع على الاستفادة من الممكنات والحوافز التي تقدمها الجهات الحكومية والخاصة، وقد توفر مزايا مرتبطة بالمنافسات والمشتريات الحكومية، مثل الإعفاء من تقديم الضمان الابتدائي والأولوية في بعض إجراءات الشراء وفق الأنظمة المعمول بها. ويمكن للشركات الناشئة إصدار الشهادة إلكترونيًا بعد استكمال بيانات المنشأة والتحقق من السجل التجاري وأعداد الموظفين والإيرادات. وتعد الوثيقة من المتطلبات المهمة للاستفادة من بعض برامج الدعم والتأهيل المخصصة للمنشآت الصغيرة والمتوسطة.$q$,$q$https://profile.monshaat.gov.sa/$q$,$q$https://profile.monshaat.gov.sa/$q$,array[$q$تمكين نظامي$q$,$q$تسهيل الحصول على الحوافز والتفضيلات$q$]::text[],array[$q$train$q$,$q$ip$q$]::text[],null,71),
  (72,$q$o9$q$,$q$أطلس الأعمال – Business Atlas$q$,$q$أداة تحليلية تفاعلية توفر بيانات ومؤشرات اقتصادية وتجارية تساعد رواد الأعمال وأصحاب المنشآت على اتخاذ قرارات مبنية على المعلومات. يتيح أطلس الأعمال استعراض بيانات القطاعات الاقتصادية في مناطق المملكة المختلفة من خلال خرائط ورسوم بيانية، بما يساعد على فهم توزيع الأنشطة التجارية ودراسة خصائص الأسواق. ويمكن للمبتكرين والشركات الناشئة الاستفادة منه عند تحديد السوق المستهدف، ودراسة فرص التوسع الجغرافي، وتحليل المنافسة، واختيار المواقع المناسبة لإطلاق المنتجات والخدمات. كما يساعد أصحاب الأفكار في إعداد الدراسات الأولية للجدوى التجارية، وتطوير افتراضات أكثر واقعية حول الأسواق والعملاء المحتملين.$q$,$q$https://atlas.monshaat.gov.sa/ar$q$,$q$https://atlas.monshaat.gov.sa/ar$q$,array[$q$دراسة الأسواق$q$,$q$تحليل البيانات$q$,$q$استكشاف الفرص التجارية$q$]::text[],array[$q$tech$q$,$q$market$q$]::text[],null,72),
  (73,$q$o10$q$,$q$بوابة التمويل – Funding Gate$q$,$q$بوابة إلكترونية موحدة يديرها بنك المنشآت الصغيرة والمتوسطة، وتتيح لأصحاب المنشآت الوصول إلى مجموعة متنوعة من الحلول التمويلية المقدمة من البنوك وشركات التمويل ومنصات التقنية المالية. يمكن للمستفيد تسجيل الدخول باستخدام النفاذ الوطني الموحد، واختيار السجل التجاري للمنشأة، وتعبئة طلب التمويل بالبيانات المالية والائتمانية، ثم إرساله إلى الجهات التمويلية المناسبة. وتتيح المنصة الاطلاع على العروض المقدمة واختيار التمويل الذي يتناسب مع احتياجات المشروع. وتعد مناسبة للشركات الناشئة والمشاريع الابتكارية التي تحتاج إلى تمويل لتطوير المنتجات أو توسيع عملياتها، بعد تأسيس المنشأة واستيفاء متطلبات الجهات التمويلية.$q$,$q$https://tamweel.smebank.gov.sa/$q$,$q$https://tamweel.smebank.gov.sa/$q$,array[$q$الوصول إلى التمويل$q$,$q$مقارنة العروض$q$,$q$الربط بالجهات التمويلية$q$]::text[],array[$q$fund$q$]::text[],null,73),
  (74,$q$o10$q$,$q$برنامج التمويل المشترك – Co-Financing Program$q$,$q$برنامج تمويلي ينفذه بنك المنشآت الصغيرة والمتوسطة بالشراكة مع البنوك التجارية المحلية، بهدف توسيع التمويل المتاح للمنشآت متناهية الصغر والصغيرة والمتوسطة. يقوم النموذج على إنشاء محافظ تمويلية مشتركة يساهم فيها بنك المنشآت والبنك التجاري الشريك، ثم يتولى الشريك إدارة المحفظة وتقديم التمويل للمنشآت المؤهلة. ويمكن لأصحاب المشاريع الاستفادة من البرنامج في تمويل احتياجات التشغيل والنمو والاستثمار بحسب المنتجات المتاحة لدى الجهات المشاركة. ويساعد هذا النموذج على زيادة قدرة القطاع المصرفي على تمويل الشركات الناشئة والمنشآت الصغيرة، وتوفير خيارات تمويلية إضافية تتناسب مع طبيعة النشاط وقدرته على السداد.$q$,$q$https://smebank.gov.sa/ar/services/programs/co-financing-model$q$,$q$https://smebank.gov.sa/ar/services/programs/co-financing-model$q$,array[$q$تمويل المنشآت عبر البنوك التجارية$q$]::text[],array[$q$fund$q$,$q$market$q$]::text[],null,74),
  (75,$q$o10$q$,$q$برنامج شركات التمويل – Finance Companies Program$q$,$q$برنامج يهدف إلى زيادة فرص تمويل المنشآت متناهية الصغر والصغيرة والمتوسطة، من خلال توفير السيولة النقدية لشركات التمويل غير البنكية المرخصة. يساعد البرنامج هذه الشركات على توسيع محافظها التمويلية وتقديم حلول متنوعة للمنشآت التي قد لا تتمكن من الحصول على التمويل المناسب عبر القنوات المصرفية التقليدية. ويستفيد أصحاب المشاريع من الخيارات التي توفرها شركات التمويل المشاركة، وفق معايير الأهلية والتقييم الائتماني لكل جهة. وتكمن أهمية البرنامج للشركات الناشئة في تنويع مصادر التمويل المتاحة، وتوفير فرص للحصول على السيولة اللازمة للعمليات التجارية وشراء المعدات وتطوير الأعمال، بحسب طبيعة المنتج التمويلي.$q$,$q$https://smebank.gov.sa/ar/services/programs/nbfi-program$q$,$q$https://smebank.gov.sa/ar/services/programs/nbfi-program$q$,array[$q$تمويل غير مباشر$q$,$q$دعم المنشآت الصغيرة والمتوسطة$q$]::text[],array[$q$fund$q$]::text[],null,75),
  (76,$q$o10$q$,$q$برنامج التمويل بالوكالة – Agency Financing Program$q$,$q$برنامج تمويلي ينفذه البنك بالتعاون مع منصات التمويل الجماعي بالدين المرخصة، بهدف توسيع الخيارات التمويلية المتاحة للمنشآت الصغيرة والمتوسطة. يخصص البنك أموالًا لمحافظ تمويلية تتولى المنصات الشريكة إدارتها وتوجيهها لتمويل المنشآت المؤهلة وفق شروط ومعايير محددة. وتتيح هذه الآلية الاستفادة من حلول التقنية المالية في تسهيل الوصول إلى التمويل وتسريع إجراءات دراسة الطلبات. ويمكن للشركات الناشئة التي لديها نشاط تجاري قائم واحتياجات تمويلية واضحة الاستفادة من المنتجات المتاحة عبر المنصات المشاركة، سواء لتغطية بعض التكاليف التشغيلية أو دعم النمو، بحسب متطلبات كل منتج والجدارة الائتمانية للمنشأة.$q$,$q$https://smebank.gov.sa/ar/services/programs/agency-model$q$,$q$https://smebank.gov.sa/ar/services/programs/agency-model$q$,array[$q$تمويل جماعي بالدين$q$,$q$تمويل نمو الشركات الناشئة$q$]::text[],array[$q$fund$q$]::text[],null,76),
  (77,$q$o10$q$,$q$برنامج ضمان التمويل «كفالة»$q$,$q$برنامج يهدف إلى تسهيل حصول المنشآت الصغيرة والمتوسطة على التمويل من خلال تقديم ضمانات للجهات الممولة، بما يقلل جزءًا من المخاطر المرتبطة بمنح التمويل. يستهدف البرنامج المنشآت التي تمتلك أنشطة ومشاريع قابلة للتمويل، لكنها قد تواجه صعوبات في توفير الضمانات المطلوبة من البنوك وشركات التمويل. وتبدأ رحلة الاستفادة بتقديم طلب التمويل إلى إحدى الجهات الشريكة أو عبر بوابة التمويل، ثم تقوم الجهة الممولة بدراسة الطلب وتحويله إلى البرنامج عند الحاجة إلى ضمان إضافي. ويوفر البرنامج منتجات متخصصة لقطاعات متعددة، منها التقنية والشركات الناشئة والتصدير، إلى جانب المنتج الاعتيادي.$q$,$q$https://www.smebank.gov.sa/ar/services/programs/loan-guarantee$q$,$q$https://www.smebank.gov.sa/ar/services/programs/loan-guarantee$q$,array[$q$ضمانات تمويلية$q$,$q$تسهيل الحصول على القروض$q$]::text[],array[$q$fund$q$]::text[],null,77),
  (78,$q$o10$q$,$q$منتج ضمان تمويل المنشآت الناشئة$q$,$q$منتج تمويلي صمم خصيصًا لدعم المنشآت الناشئة خلال السنوات الثلاث الأولى من ممارسة النشاط التجاري، وهي المرحلة التي تواجه فيها العديد من المشاريع صعوبة في الحصول على التمويل بسبب محدودية السجل الائتماني أو الضمانات. يقدم البرنامج ضمانًا للجهة الممولة قد يصل إلى 90% من قيمة التمويل، مع حدود قصوى للضمان تختلف بحسب حجم المنشأة. ويمكن أن تستفيد منه الشركات التقنية والابتكارية التي بدأت نشاطها التجاري وتحتاج إلى موارد مالية لاستكمال تطوير المنتجات أو تغطية التكاليف التشغيلية والتوسع. وتخضع الموافقة لدراسة الجهة الممولة والبرنامج، ولا يشكل الضمان موافقة تلقائية على التمويل.$q$,$q$https://www.smebank.gov.sa/ar/services/programs/loan-guarantee$q$,$q$https://www.smebank.gov.sa/ar/services/programs/loan-guarantee$q$,array[$q$ضمان تمويل الشركات خلال سنواتها الأولى$q$]::text[],array[$q$fund$q$,$q$prod$q$]::text[],null,78),
  (79,$q$o10$q$,$q$منتجات ضمان تمويل القطاعات الناشئة$q$,$q$منتجات متخصصة يهدف إلى تمكين المنشآت العاملة في قطاعات ناشئة من الحصول على التمويل اللازم لتطوير أعمالها. ويستهدف الشركات متناهية الصغر والصغيرة والمتوسطة المصنفة ضمن الأنشطة الناشئة الاقتصادية الناشئة. ويمكن للشركات الناشئة الاستفادة منه عند الحاجة إلى تمويل لتوسيع العمليات أو تطوير المنتجات. ويتم تقديم طلب التمويل عبر الجهات المشاركة أو بوابة التمويل، مع خضوع الطلب للتقييم الائتماني والشروط المعتمدة.$q$,$q$https://www.smebank.gov.sa/ar/services/loan-guarantee-products$q$,$q$https://www.smebank.gov.sa/ar/services/loan-guarantee-products$q$,array[$q$ضمانات تمويلية للشركات في القطاعات الناشئة$q$]::text[],array[$q$fund$q$,$q$prod$q$]::text[],null,79),
  (80,$q$o10$q$,$q$منتج ضمان تمويل رأس المال العامل$q$,$q$منتج يستهدف المنشآت الصغيرة والمتوسطة التي تحتاج إلى تمويل رأس المال العامل لتغطية المصروفات المرتبطة باستمرار الأنشطة التجارية والتشغيلية. ويمكن استخدام التمويل الذي تتيحه الجهة الممولة لأغراض مؤهلة مثل شراء المواد والمخزون، أو تغطية التكاليف التشغيلية، أو الوفاء بالالتزامات المرتبطة بتنفيذ الطلبات التجارية. ويوفر البرنامج ضمانًا تمويليًا قد يصل إلى 90% وفق الحدود والشروط المحددة. ويعد مناسبًا للشركات الناشئة التي بدأت بيع منتجاتها أو تقديم خدماتها وتحتاج إلى سيولة للمحافظة على عملياتها أو تلبية طلبات جديدة، دون أن يكون المنتج مخصصًا لتمويل البحث العلمي أو النماذج الأولية غير التجارية.$q$,null,null,array[]::text[],array[$q$fund$q$,$q$prod$q$]::text[],null,80),
  (81,$q$o10$q$,$q$المنتج الاعتيادي لضمان التمويل$q$,$q$منتج عام ضمن برنامج كفالة، يستهدف المنشآت الصغيرة والمتوسطة العاملة في قطاعات وأنشطة تجارية لا تشملها المنتجات التمويلية المتخصصة الأخرى. يقدم ضمانًا يصل إلى 80% من قيمة التمويل، ضمن حدود قصوى تختلف بحسب تصنيف حجم المنشأة. ويمكن للشركات الناشئة والمشاريع الابتكارية ذات الأنشطة التجارية المؤهلة الاستفادة منه عندما لا ينطبق عليها أحد المنتجات القطاعية المتخصصة. ويساعد الضمان على تعزيز فرص الحصول على تمويل من البنوك أو شركات التمويل المتعاونة، مع بقاء قرار منح التمويل وشروطه لدى الجهة الممولة. ويُعد خيارًا مناسبًا للمشاريع التي لديها نموذج أعمال واضح واحتياج تمويلي قابل للدراسة.$q$,$q$https://www.smebank.gov.sa/ar/services/loan-guarantee-products/regular-financing-guarantee-product$q$,$q$https://www.smebank.gov.sa/ar/services/loan-guarantee-products/regular-financing-guarantee-product$q$,array[$q$ضمانات تمويلية للأنشطة التجارية المختلفة$q$]::text[],array[$q$fund$q$,$q$prod$q$,$q$market$q$]::text[],null,81),
  (82,$q$o10$q$,$q$منتجات تمويل رأس المال العامل والتمويل لأجل والتمويل متناهي الصغر$q$,$q$تشمل المنتجات التمويلية التي يعرّف بها البنك حلولًا متعددة، منها التمويل متناهي الصغر، وتمويل رأس المال العامل، والتمويل لأجل، والتمويل بحد ائتماني متجدد، وتمويل التجارة الإلكترونية. وتختلف المنتجات بحسب احتياجات المنشأة ومرحلة نموها، إذ يستهدف بعضها تغطية المتطلبات التشغيلية قصيرة الأجل، بينما يمكن استخدام منتجات أخرى لتمويل الاستثمارات والمعدات وتطوير الأعمال. وتساعد هذه الخيارات أصحاب الشركات الناشئة على اختيار نوع التمويل المناسب لطبيعة مشروعهم وقدرته على السداد. وتخضع شروط التمويل وحدوده ومدده للمنتج المختار والجهة الممولة والسياسات الائتمانية المعتمدة، ولا تتاح جميع المنتجات بالضرورة لدى جميع الشركاء.$q$,$q$https://tamweel.smebank.gov.sa/$q$,$q$https://tamweel.smebank.gov.sa/$q$,array[$q$تمويل تشغيلي واستثماري$q$]::text[],array[$q$fund$q$,$q$invest$q$,$q$prod$q$]::text[],null,82),
  (83,$q$o10$q$,$q$خدمة دعم المستفيدين في مراكز دعم المنشآت$q$,$q$خدمة يقدمها ممثلو بنك المنشآت الصغيرة والمتوسطة في مراكز دعم المنشآت، بهدف مساعدة رواد الأعمال وأصحاب المشاريع على التعرف على المنتجات التمويلية المتاحة وآليات التقديم عليها. تتضمن الخدمة شرح شروط الحصول على التمويل والمستندات المطلوبة، وتقديم الإرشاد حول استخدام بوابة التمويل، ومساعدة المستفيدين عند مواجهة صعوبات أثناء تقديم الطلبات. كما يمكن للمستفيد الاستفسار عن الخيارات المناسبة لطبيعة نشاطه ومرحلة نموه، دون أن يعني ذلك ضمان الموافقة على التمويل. ويتم حجز المواعيد عبر تطبيق نوافذ، من خلال اختيار الاستشارات ثم الشراكات وتحديد بنك المنشآت الصغيرة والمتوسطة.$q$,$q$https://smebank.gov.sa/ar/services/support-centers$q$,$q$https://smebank.gov.sa/ar/services/support-centers$q$,array[$q$استشارات تمويلية$q$,$q$إرشاد في التقديم$q$]::text[],array[$q$fund$q$,$q$mentor$q$]::text[],null,83),
  (84,$q$o11$q$,$q$باقة رواد$q$,$q$حزمة مصممة لرواد الأعمال والشركات الناشئة تساعدهم في عملية التحقق من بيانات عملائهم الأفراد من خلال الربط الالكتروني مع مركز المعلومات الوطني لتحقيق أعلى مستويات الأمان والموثوقية بتكلفة منخفضة.$q$,$q$https://sdaia.gov.sa/ar/Investment/Pages/RowadInitiative.aspx$q$,$q$https://sdaia.gov.sa/ar/Investment/Pages/RowadInitiative.aspx$q$,array[$q$استشارات تقنية$q$,$q$الأمن السيبراني$q$]::text[],array[$q$mentor$q$,$q$tech$q$]::text[],null,84),
  (85,$q$o11$q$,$q$مسرعات الأعمال$q$,$q$برامج مكثفة ومتكاملة  تهدف إلى تمكين وتسريع نمو الشركات الناشئة في البيانات والذكاء الاصطناعي. وتسليط الضوء على دور المملكة العربية السعودية النشط في مجال البيانات والذكاء الاصطناعي. والمساهمة في إنشاء مجتمع للشركات الناشئة المحلية والدولية في مجال البيانات والذكاء الاصطناعي.$q$,$q$https://sdaia.gov.sa/ar/Investment/Pages/BusinessAccelerators.aspx$q$,$q$https://sdaia.gov.sa/ar/Investment/Pages/BusinessAccelerators.aspx$q$,array[$q$تسريع أعمال$q$,$q$تطوير منتجات$q$,$q$استثمار$q$]::text[],array[$q$invest$q$,$q$incub$q$,$q$prod$q$]::text[],null,85),
  (86,$q$o11$q$,$q$برنامج البيئة التنظيمية التجريبية للبيانات – Data Regulatory Sandbox$q$,$q$برنامج يتيح للشركات والجهات المؤهلة اختبار المنتجات والخدمات القائمة على البيانات ضمن بيئة خاضعة للإشراف التنظيمي، قبل التوسع في تطبيقها تجاريًا. يساعد المشاركين على تقييم مدى توافق منتجاتهم مع المتطلبات المتعلقة بحماية البيانات الشخصية وحوكمتها، واكتشاف التحديات التنظيمية التي قد تواجههم أثناء التشغيل. ويشمل البرنامج مسارين رئيسيين، هما حماية البيانات الشخصية وتحقيق الإيرادات من البيانات، بحسب طبيعة الجهة والمنتج. وتوفر البيئة إرشادات واستشارات وورش عمل متخصصة دون مقابل، مع إمكانية الحصول على شهادة إتمام عند استيفاء المتطلبات. وتعد مناسبة للشركات الناشئة التي تقدم خدمات تعتمد على معالجة البيانات أو تطوير تقنيات حماية الخصوصية.$q$,$q$https://dgp.sdaia.gov.sa/wps/portal/pdp/services/dataregulatorysandbox$q$,$q$https://dgp.sdaia.gov.sa/wps/portal/pdp/services/dataregulatorysandbox$q$,array[$q$اختبار تنظيمي$q$,$q$إرشاد$q$,$q$تطوير منتجات قائمة على البيانات$q$]::text[],array[$q$mentor$q$,$q$prod$q$,$q$tech$q$,$q$ip$q$]::text[],null,86),
  (87,$q$o11$q$,$q$البيئة التجريبية التقنية لتطبيق توكلنا – Tawakkalna Sandbox$q$,$q$مبادرة تتيح لشركات القطاع الخاص اختبار خدماتها الرقمية ضمن البيئة التقنية للتطبيق الوطني الشامل «توكلنا»، تمهيدًا لإمكانية تقديمها للمستخدمين وفق الضوابط المعتمدة. توفر البيئة للمشاركين الوصول المبكر إلى المنصة، والدعم الفني، والجلسات الإرشادية والاستشارية من خبراء سدايا، إلى جانب اختبار تكامل الخدمات وتحسين تجربة المستخدم قبل الإطلاق. وتستهدف الشركات التي تمتلك سجلًا تجاريًا وتراخيص نظامية سارية وخدمات رقمية تتوافق مع متطلبات الحوكمة والأمن والجودة. وتمثل المبادرة فرصة للشركات الناشئة التي تقدم خدمات موجهة للأفراد وترغب في اختبار قابليتها للتكامل مع منصة وطنية واسعة الانتشار، وتعزيز فرص وصول خدماتها إلى المستخدمين.$q$,$q$https://partners.tawakkalna.sa/home/$q$,$q$https://partners.tawakkalna.sa/home/$q$,array[$q$اختبار منتجات رقمية$q$,$q$تكامل تقني$q$,$q$وصول للمستخدمين$q$,$q$إرشاد$q$]::text[],array[$q$mentor$q$,$q$prod$q$,$q$tech$q$,$q$market$q$]::text[],null,87),
  (88,$q$o11$q$,$q$خدمة طلب البيانات المفتوحة من سدايا$q$,$q$خدمة إلكترونية تتيح للأفراد والباحثين والشركات تقديم طلبات للحصول على مجموعات بيانات مفتوحة من سدايا، ضمن الإطار التنظيمي المعتمد لإتاحة البيانات العامة. تتضمن الخدمة نموذجًا لتحديد نوع البيانات المطلوبة والغرض من استخدامها وطبيعة النشاط والجهة المستفيدة. ويمكن للمبتكرين الاستفادة منها في إجراء الدراسات وتحليل البيانات وتطوير النماذج الأولية للحلول الرقمية، خاصة المشاريع التي تعتمد على التحليل الإحصائي أو تقنيات الذكاء الاصطناعي. كما تساعد على توظيف البيانات المتاحة بصورة نظامية في تطوير حلول جديدة ودعم القرارات البحثية والتجارية. وتخضع الطلبات للمراجعة، ولا تضمن الخدمة إتاحة جميع مجموعات البيانات المطلوبة.$q$,$q$https://sdaia.gov.sa/ar/Research/pages/opendatarequest.aspx$q$,$q$https://sdaia.gov.sa/ar/Research/pages/opendatarequest.aspx$q$,array[$q$بيانات مفتوحة$q$,$q$بحث وتطوير$q$,$q$اختبار النماذج التحليلية$q$]::text[],array[$q$prod$q$,$q$tech$q$,$q$ip$q$]::text[],null,88),
  (89,$q$o11$q$,$q$المنصة الوطنية لبناء القدرات - أذكى athkax$q$,$q$منصة وطنية أطلقتها سدايا خلال عام 2026 بهدف تمكين الكفاءات والمواهب السعودية من تطوير مهاراتها في مجالات البيانات والذكاء الاصطناعي. توفر المنصة مسارات تعليمية وتدريبية متخصصة ترتبط بالاحتياجات المهنية والتقنية، بالتعاون مع شركات تقنية عالمية ومؤسسات أكاديمية، من بينها Microsoft وAWS وIBM وNVIDIA وOracle. وتشمل خدماتها البرامج التدريبية المتقدمة وسجلًا مهاريًا وطنيًا يوثق تطور مهارات المشاركين. ويمكن للمبتكرين ورواد الأعمال الاستفادة من المنصة لتطوير قدراتهم التقنية أو تأهيل أعضاء فرقهم في التخصصات المطلوبة لبناء حلول الذكاء الاصطناعي وتطوير المنتجات الرقمية، وتعزيز قدرتهم على استخدام التقنيات الحديثة في مشاريعهم.$q$,$q$https://athkax.sdaia.gov.sa/$q$,$q$https://athkax.sdaia.gov.sa/$q$,array[$q$تدريب تقني$q$,$q$مسارات تخصصية$q$,$q$تطوير مهارات الذكاء الاصطناعي$q$]::text[],array[$q$train$q$,$q$tech$q$]::text[],null,89),
  (90,$q$o11$q$,$q$مبادرة مليون سعودي للذكاء الاصطناعي «سماي» – SAMAI$q$,$q$مبادرة وطنية أطلقتها سدايا بالتعاون مع وزارة التعليم ووزارة الموارد البشرية والتنمية الاجتماعية، بهدف تمكين مليون مواطن ومواطنة من اكتساب المعرفة والمهارات الأساسية المرتبطة بالذكاء الاصطناعي. يقدم البرنامج محتوى تدريبيًا باللغة العربية عن بُعد، بأسلوب التعلم الذاتي، ويتناول تطبيقات الذكاء الاصطناعي واستخدامه المسؤول والأخلاقي في الحياة والعمل. ويمكن لرواد الأعمال والطلاب والباحثين الاستفادة منه في التعرف على إمكانات توظيف الذكاء الاصطناعي في تطوير المنتجات والخدمات، وتحسين الإنتاجية ودعم اتخاذ القرار. ويحصل المتدربون الذين يستكملون البرنامج بنجاح على شهادة معتمدة من سدايا، وفق متطلبات المبادرة.$q$,$q$https://samai.futurex.sa/$q$,$q$https://samai.futurex.sa/$q$,array[$q$تدريب مجاني$q$,$q$تطوير المعرفة$q$,$q$شهادة معتمدة$q$]::text[],array[$q$train$q$,$q$tech$q$]::text[],null,90),
  (91,$q$o12$q$,$q$مشروع تمكين المستثمر من خلال سلاسل الإمداد$q$,$q$مبادرة أطلقتها الهيئة لتمكين الشركات المحلية والمستثمرين من الاستفادة من فرص توطين المنتجات والخدمات في قطاع الصناعات العسكرية. وتعتمد على دراسة سلاسل الإمداد وتحديد الفجوات في القدرات الصناعية، ومن ثم طرح الفرص التي يمكن للمصنعين والموردين المحليين الاستثمار فيها. ويساعد المشروع على ربط الشركات المحلية بالشركات العالمية والمصنعين الأصليين، والتعريف بمتطلبات القطاع وفرص الدخول إليه. وقد حددت الهيئة من خلال المشروع 74 فرصة استثمارية في ستة مجالات دفاعية وأمنية. وتبرز أهميته للمبتكرين الذين يمتلكون منتجات أو تقنيات ذات استخدامات صناعية وعسكرية مشتركة، ويرغبون في استكشاف فرص تطويرها وتصنيعها محليًا.$q$,$q$https://marketplace.gami.gov.sa$q$,$q$marketplace.gami.gov.sa$q$,array[$q$فرص استثمارية$q$,$q$توطين صناعي$q$,$q$ربط بالشركات الكبرى$q$]::text[],array[$q$invest$q$,$q$market$q$]::text[],null,91),
  (92,$q$o12$q$,$q$خدمة الفرص الاستثمارية في قطاع الصناعات العسكرية$q$,$q$خدمة تتيح للمستثمرين ورواد الأعمال والشركات المحلية والدولية الاطلاع على الفرص الاستثمارية التي تعلنها الهيئة في قطاع الصناعات العسكرية. وتشمل الفرص أنشطة تصنيع وتوريد وخدمات مرتبطة بسلاسل الإمداد، مع إمكانية التعرف على متطلبات كل فرصة وتقديم الاهتمام بالمشاركة فيها. وتستهدف الخدمة الشركات التي تمتلك قدرات صناعية قائمة أو تخطط للاستثمار في منتجات وتقنيات جديدة ذات احتياجات واضحة في القطاع. ويمكن للمبتكرين وأصحاب المنتجات الهندسية الاستفادة منها لتحديد المجالات الصناعية التي تتطلب حلولًا محلية، ودراسة إمكانية تطوير منتجاتهم أو تقنياتهم لتلبية تلك الاحتياجات. وتخضع المشاركة لمتطلبات الفرص المطروحة والأنظمة ذات العلاقة.$q$,$q$https://www.gami.gov.sa/ar/opportunity-contact$q$,$q$https://www.gami.gov.sa/ar/opportunity-contact$q$,array[$q$استكشاف فرص السوق$q$,$q$الاستثمار$q$,$q$الشراكات الصناعية$q$]::text[],array[$q$invest$q$,$q$market$q$]::text[],null,92),
  (93,$q$o12$q$,$q$خدمة ملف قدرة الشركة وعلاقات الصناعة$q$,$q$خدمة تتيح للشركات المصنعة والموردة في قطاع الصناعات العسكرية تسجيل قدراتها الفنية والتشغيلية وتقييم جاهزيتها للمشاركة في مشاريع القطاع. وتهدف إلى تكوين صورة واضحة عن إمكانات الشركات المحلية، بما يساعد الهيئة على تحديد فرص التوطين والاستثمار والتكامل بين المنشآت. ويمكن للشركات الاستفادة منها للتعريف بقدراتها الإنتاجية وخبراتها الصناعية ومجالات تخصصها، ودعم فرص التعاون مع الجهات العاملة في القطاع. وتعد مناسبة للشركات التي تمتلك تقنيات أو منتجات صناعية قابلة للتطبيق في الصناعات العسكرية، وتسعى إلى إبراز قدراتها وتطوير حضورها ضمن سلاسل الإمداد المحلية.$q$,$q$https://www.gami.gov.sa/ar/unified-military-industries-portal/establishment-capability-file-and-industry-relationship-services$q$,$q$https://www.gami.gov.sa/ar/unified-military-industries-portal/establishment-capability-file-and-industry-relationship-services$q$,array[$q$تقييم القدرات$q$,$q$تأهيل الموردين$q$,$q$فرص التعاون الصناعي$q$]::text[],array[$q$train$q$,$q$market$q$,$q$ip$q$]::text[],null,93),
  (94,$q$o12$q$,$q$إصدار ترخيص للتصنيع العسكري$q$,$q$خدمة إلكترونية تتيح للمنشآت المؤهلة الحصول على الترخيص النظامي لمزاولة نشاط التصنيع العسكري في المملكة، بعد استكمال متطلبات الجهات المختصة. وتشمل إجراءات الترخيص التحقق من بيانات الشركة والنشاط الصناعي، والتصريح التأسيسي، ومتطلبات السلامة والأمن الصناعي وغيرها من الاشتراطات ذات العلاقة. وتعد الخدمة ضرورية للشركات التي تخطط لتصنيع المنتجات والمكونات المخصصة للاستخدامات العسكرية، بما في ذلك الشركات التي طورت تقنيات أو منتجات مبتكرة ووصلت إلى مرحلة الإنتاج. وتساعد الخدمة على استكمال الإجراءات التنظيمية اللازمة لدخول القطاع بصورة نظامية، مع خضوع الطلب للدراسة والموافقة قبل إصدار الترخيص النهائي.$q$,$q$https://www.gami.gov.sa/ar/unified-military-industries-portal/asdar-trkhys-lltsny-alskry$q$,$q$https://www.gami.gov.sa/ar/unified-military-industries-portal/asdar-trkhys-lltsny-alskry$q$,array[$q$ترخيص صناعي$q$,$q$تمكين الإنتاج التجاري$q$]::text[],array[$q$prod$q$,$q$market$q$,$q$ip$q$]::text[],null,94),
  (95,$q$o13$q$,$q$برنامج تقدّم لتسريع الأعمال – TAQADAM Startup Accelerator$q$,$q$برنامج لتسريع نمو الشركات الناشئة، يقدم رحلة تطوير مكثفة تمتد ستة أشهر لمساعدة رواد الأعمال على تحويل ابتكاراتهم إلى مشاريع تجارية قابلة للنمو. يركز البرنامج على تطوير المنتجات، والتحقق من احتياجات السوق، وتحسين نماذج الأعمال، وبناء فرق العمل، والاستعداد للحصول على الاستثمار. ويوفر إرشادًا من خبراء ورواد أعمال، ومساحات عمل، وفرص التواصل مع المستثمرين والعملاء المحتملين. تحصل الشركات المختارة على تمويل غير مسترد بقيمة 40 ألف دولار، مع إمكانية حصول المشاريع المتميزة على تمويل إضافي يصل إلى 100 ألف دولار. ويستقبل البرنامج مشاريع من مختلف القطاعات، بما فيها المشاريع التقنية والابتكارية التي تخطط للعمل أو التوسع في المملكة.$q$,$q$https://taqadam.kaust.edu.sa/ar$q$,$q$https://taqadam.kaust.edu.sa/ar$q$,array[$q$تسريع أعمال$q$,$q$منح مالية$q$,$q$إرشاد$q$,$q$استثمار$q$]::text[],array[$q$fund$q$,$q$invest$q$,$q$mentor$q$,$q$incub$q$]::text[],null,95),
  (96,$q$o13$q$,$q$استوديو المشاريع الريادية – KAUST Venture Studio$q$,$q$برنامج يستهدف رواد الأعمال الذين يمتلكون أفكارًا أو فرصًا لتطوير منتجات جديدة، ويحتاجون إلى تحويلها إلى شركات ناشئة. يقدم الاستوديو رحلة تطوير تتراوح بين ثلاثة وستة أشهر، تركز على ثلاثة عناصر رئيسية: بناء الفريق المؤسس، وتطوير المنتج الأولي، والوصول إلى أول عميل. يساعد البرنامج المؤسسين على اختبار افتراضاتهم التجارية والتقنية، وتطوير نموذج أولي قابل للاستخدام، والتواصل مع العملاء المحتملين بهدف تحقيق أول إيرادات للمشروع. ويمكن التقديم بفريق يضم مؤسسًا واحدًا على الأقل، بشرط وجود قدرة تقنية داخل الفريق لتطوير المنتج. ولا يشترط وجود خبرة سابقة في تأسيس الشركات.$q$,$q$https://www.kaust.edu.sa/en/innovate/kaust-entrepreneurship-programs$q$,$q$https://www.kaust.edu.sa/en/innovate/kaust-entrepreneurship-programs$q$,array[$q$احتضان الأفكار$q$,$q$تطوير المنتجات$q$,$q$تأسيس شركات$q$]::text[],array[$q$incub$q$,$q$prod$q$]::text[],null,96),
  (97,$q$o13$q$,$q$برنامج كاوست للتوسع – KAUST ScaleX$q$,$q$برنامج يستهدف الشركات التقنية الدولية التي ترغب في التوسع إلى المملكة العربية السعودية وتأسيس حضور تجاري فيها. يوفر البرنامج خدمات الدخول إلى السوق، والتعرف على البيئة التنظيمية والاستثمارية، والتواصل مع الجهات الحكومية والشركات الكبرى والمستثمرين، إضافة إلى الاستفادة من المختبرات والخبرات البحثية لدى كاوست. كما يقدم مساحات عمل ودعمًا في إجراءات التأسيس وفرصًا لتنفيذ مشاريع تجريبية مع شركاء محتملين. ويستهدف الشركات التي مضى على تأسيسها عامان على الأقل، وسبق لها الحصول على تمويل من الفئة B أو ما يعادله، وتمتلك منتجات جاهزة للتطبيق التجاري. ولا يقدم البرنامج استثمارًا ماليًا مباشرًا ضمن خدماته الأساسية.$q$,$q$https://scalex.kaust.edu.sa/$q$,$q$https://scalex.kaust.edu.sa/$q$,array[$q$دخول السوق السعودي$q$,$q$الشراكات$q$,$q$الخدمات اللوجستية$q$]::text[],array[$q$market$q$]::text[],null,97),
  (98,$q$o13$q$,$q$صندوق كاوست للاستثمار الجريء – KAUST Innovation Ventures (KIV)$q$,$q$يقدم صندوق كاوست للاستثمار الجريء تمويلًا للشركات الناشئة القائمة على التقنيات العميقة، خصوصًا في مجالات الصحة والطاقة والغذاء والمياه والذكاء الاصطناعي. يستثمر الصندوق في الشركات المنبثقة من كاوست، والشركات التقنية السعودية الواعدة، والشركات الدولية التي تتوسع في المملكة. ويستهدف المراحل الاستثمارية المبكرة، من مرحلة ما قبل التمويل التأسيسي حتى الجولة الاستثمارية A المبكرة. وإلى جانب الاستثمار المالي، يوفر للشركات دعمًا استراتيجيًا وتوجيهًا استثماريًا وإمكانية الاستفادة من الخبرات البحثية وشبكات الشركاء والمستثمرين. ويركز على الشركات التي تمتلك فريقًا مؤسسًا متكاملًا ومنتجًا قابلًا للتسويق ومؤشرات أولية على الطلب التجاري.$q$,$q$https://www.kaust.edu.sa/en/innovate/kaust-innovation-ventures$q$,$q$https://www.kaust.edu.sa/en/innovate/kaust-innovation-ventures$q$,array[$q$استثمار جريء$q$,$q$تمويل تأسيسي$q$,$q$إرشاد استثماري$q$,$q$تطوير شركات تقنية$q$]::text[],array[$q$fund$q$,$q$invest$q$,$q$mentor$q$,$q$incub$q$,$q$prod$q$]::text[],null,98),
  (99,$q$o13$q$,$q$مختبر النمذجة وتطوير المنتجات – Prototyping and Product Development Core Lab (PCL)$q$,$q$مختبر متخصص في تطوير النماذج الأولية والمنتجات الهندسية، يوفر أجهزة وتجهيزات متقدمة وخبرات فنية لدعم المشاريع البحثية والابتكارية. تشمل خدمات المختبر التصميم باستخدام الحاسب الآلي، والهندسة العكسية، والتصنيع بالإضافة والطباعة ثلاثية الأبعاد، والتشغيل باستخدام ماكينات CNC، واللحام، وتصنيع الدوائر الإلكترونية والأنظمة الميكاترونية. كما يوفر خدمات التصميم الميكانيكي وتحليل الإجهادات وتطوير الأجهزة العلمية، إلى جانب التدريب والإرشاد الفني. ويمكن للمبتكرين والباحثين الاستفادة من قدراته لتحويل التصاميم إلى نماذج فعلية، واختبار وظائف المنتجات وتحسينها قبل الانتقال إلى مراحل التصنيع التجاري. وتخضع الاستفادة الخارجية لترتيبات الوصول والخدمة المعتمدة لدى الجامعة.$q$,$q$https://corelabs.kaust.edu.sa/labs/detail/prototyping-product-development-core-lab$q$,$q$https://corelabs.kaust.edu.sa/labs/detail/prototyping-product-development-core-lab$q$,array[$q$نمذجة أولية$q$,$q$تصنيع تجريبي$q$,$q$تصميم هندسي$q$,$q$اختبارات فنية$q$]::text[],array[$q$prod$q$,$q$space$q$]::text[],null,99),
  (100,$q$o13$q$,$q$ماجستير الابتكار التقني وريادة الأعمال (TIE)$q$,$q$برنامج ماجستير متخصص لمدة 16 شهرًا، يهدف إلى تأهيل المبتكرين ورواد الأعمال لتحويل الأفكار والتقنيات إلى منتجات ومشاريع تجارية قابلة للنمو. يجمع البرنامج بين الدراسة الأكاديمية والتطبيق العملي في مجالات التفكير التصميمي، وتطوير المنتجات، والتصنيع، والذكاء الاصطناعي، وريادة الأعمال. ويتيح للمشاركين الاستفادة من مختبرات كاوست المتقدمة وخبرات الباحثين والموجهين، إلى جانب تدريب دولي لمدة ثلاثة إلى أربعة أشهر في أحد مراكز الابتكار العالمية. ويحصل الطلاب المقبولون على منحة دراسية تشمل الرسوم الدراسية ومخصصًا شهريًا ومزايا أخرى. يستهدف البرنامج خريجي التخصصات العلمية والهندسية الراغبين في تطوير ابتكاراتهم وتأسيس مشاريع تقنية ناشئة$q$,$q$https://tie.kaust.edu.sa/$q$,$q$https://tie.kaust.edu.sa/$q$,array[$q$برنامج اكاديمي للابتكار وريادة الأعمال$q$]::text[],array[$q$train$q$]::text[],null,100),
  (101,$q$o14$q$,$q$خدمة المسار السريع$q$,$q$خدمة مخصصة لمساعدة رواد الأعمال وأصحاب المنشآت الصغيرة والمتوسطة على التعامل مع الإجراءات الحكومية التي قد تواجههم عند تأسيس مشاريعهم أو تطويرها. تعمل الخدمة من خلال مختصين يساعدون المستفيدين على تحديد المتطلبات والإجراءات ذات العلاقة، والتواصل مع الجهات المختصة لمعالجة المعوقات التي تؤثر في ممارسة الأعمال. ويمكن للمبتكرين الذين يرغبون في تحويل ابتكاراتهم إلى مشاريع تجارية الاستفادة منها في التعرف على متطلبات النشاط، وتحديد الجهات الحكومية المعنية بالتراخيص أو الإجراءات التنظيمية، والحصول على التوجيه المناسب. ولا تعني الخدمة الإعفاء من المتطلبات النظامية أو ضمان الموافقة على الطلبات المقدمة للجهات الحكومية.$q$,$q$https://chamber.sa/ChamberServices/YoungBusinessmenServices/Pages/FastTrack.aspx$q$,$q$https://chamber.sa/ChamberServices/YoungBusinessmenServices/Pages/FastTrack.aspx$q$,array[$q$تسهيل الإجراءات الحكومية$q$,$q$معالجة التحديات التنظيمية$q$]::text[],array[$q$compete$q$,$q$ip$q$]::text[],null,101),
  (102,$q$o14$q$,$q$خدمة المكاتب المشتركة المؤقتة$q$,$q$خدمة تتيح لرواد الأعمال الاستفادة من مكاتب ومساحات عمل مشتركة ضمن بيئة مهنية تساعد على تطوير المشاريع وإدارة الأنشطة التجارية في مراحلها المبكرة. وتهدف إلى توفير بيئة عمل مناسبة لأصحاب المشاريع الريادية، مع إمكانية الاستفادة من الخبرات المتاحة في مركز ريادة الأعمال والخدمات المرتبطة به. ويمكن أن يستفيد منها المبتكرون الذين يعملون على تأسيس شركات ناشئة ويحتاجون إلى مساحة عمل مؤقتة لعقد الاجتماعات أو تنظيم أنشطة الفريق أو التواصل مع الجهات الداعمة. وتخضع الاستفادة من المكاتب لتوافر المساحات وشروط القبول ومدد الاستخدام التي يحددها المركز.$q$,$q$https://chamber.sa/ChamberServices/YoungBusinessmenServices/Pages/WorkspaceRegister.aspx$q$,$q$https://chamber.sa/ChamberServices/YoungBusinessmenServices/Pages/WorkspaceRegister.aspx$q$,array[$q$مساحات عمل$q$,$q$بيئة ريادية$q$,$q$تطوير أعمال$q$]::text[],array[$q$incub$q$,$q$space$q$]::text[],null,102),
  (103,$q$o15$q$,$q$برنامج AWS Activate Founders$q$,$q$برنامج مخصص للشركات الناشئة التي تعتمد على التمويل الذاتي ولم تحصل على دعم من إحدى الجهات الاستثمارية أو مسرعات الأعمال المعتمدة لدى AWS. يقدم البرنامج اعتمادات مالية لاستخدام الخدمات السحابية، تبدأ بقيمة 1,000 دولار، مع إمكانية حصول الشركات المؤهلة على اعتمادات إضافية تصل إلى 5,000 دولار. ويمكن استخدام الاعتمادات في بناء وتشغيل التطبيقات والمنصات الرقمية، وتخزين البيانات، وتشغيل نماذج الذكاء الاصطناعي، واختبار المنتجات الأولية قبل إطلاقها تجاريًا. ويستهدف الشركات التي تأسست خلال السنوات العشر الأخيرة وتمتلك موقعًا إلكترونيًا فعّالًا، مع استيفاء متطلبات التسجيل لدى AWS. ويساعد البرنامج على تقليل التكاليف التقنية خلال المراحل الأولى من تطوير المشروع.$q$,$q$https://aws.amazon.com/startups/credits/$q$,$q$https://aws.amazon.com/startups/credits/$q$,array[$q$اعتمادات سحابية$q$,$q$تطوير نماذج أولية$q$,$q$تقليل تكاليف التشغيل$q$]::text[],array[$q$fund$q$,$q$prod$q$,$q$tech$q$]::text[],null,103),
  (104,$q$o15$q$,$q$برنامج AWS Activate Portfolio$q$,$q$برنامج يقدم اعتمادات سحابية للشركات الناشئة التي ترتبط بمسرعات أعمال أو حاضنات أو مستثمرين معتمدين لدى AWS. ويتيح للشركات المؤهلة الحصول على اعتمادات قد تصل إلى 200 ألف دولار لاستخدام خدمات الحوسبة السحابية والذكاء الاصطناعي وتخزين البيانات والبنية التحتية الرقمية. ويمكن الاستفادة منها في تطوير المنتجات التقنية، وإجراء التجارب، وتدريب نماذج الذكاء الاصطناعي وتشغيلها، والتوسع في تقديم الخدمات للعملاء. يشترط البرنامج أن تكون الشركة في مرحلة تسبق الجولة الاستثمارية B، وأن تحصل على رمز تعريف المنظمة (Org ID) من جهة داعمة معتمدة. ويساعد البرنامج المشاريع التقنية ذات النمو المرتفع على تقليل تكاليف التطوير والتشغيل.$q$,$q$https://aws.amazon.com/startups/credits/$q$,$q$https://aws.amazon.com/startups/credits/$q$,array[$q$اعتمادات سحابية$q$,$q$دعم تقني$q$,$q$تطوير منتجات$q$]::text[],array[$q$fund$q$,$q$mentor$q$,$q$prod$q$,$q$tech$q$]::text[],null,104),
  (105,$q$o15$q$,$q$برنامج AWS Free Tier – المستوى المجاني$q$,$q$يوفر المستوى المجاني من AWS فرصة للأفراد والمبتكرين والمطورين لتجربة الخدمات السحابية وبناء النماذج الأولية للتطبيقات الرقمية قبل الالتزام بتكاليف تشغيلية كبيرة. يحصل العملاء الجدد على اعتماد بقيمة 100 دولار عند إنشاء الحساب، مع إمكانية الحصول على 100 دولار إضافية عند استكشاف خدمات محددة، ليصل إجمالي الاعتمادات إلى 200 دولار. وتتيح الخطة المجانية تجربة مجموعة من خدمات الحوسبة والتخزين وقواعد البيانات والذكاء الاصطناعي لمدة تصل إلى ستة أشهر أو حتى استنفاد الاعتمادات، أيهما أسبق. ويمكن للطلاب والباحثين وأصحاب الأفكار الاستفادة منها لبناء منتجات أولية واختبارها، مع الانتباه إلى حدود الاستخدام والخدمات المشمولة.$q$,$q$https://aws.amazon.com/free/$q$,$q$https://aws.amazon.com/free/$q$,array[$q$اعتمادات مجانية$q$,$q$بنية تحتية سحابية$q$,$q$تطوير نماذج أولية$q$]::text[],array[$q$fund$q$,$q$prod$q$,$q$tech$q$,$q$space$q$]::text[],null,105),
  (106,$q$o15$q$,$q$عروض AWS Activate الحصرية – Activate Exclusive Offers$q$,$q$توفر AWS للشركات الناشئة المؤهلة ضمن منظومة Activate مجموعة من العروض والخصومات المقدمة من شركات تقنية وشركاء متخصصين. تشمل العروض أدوات تطوير البرمجيات، وخدمات الذكاء الاصطناعي وتحليل البيانات، وأدوات إدارة العملاء والتسويق، والأمن السيبراني، والإدارة المالية وغيرها. ويمكن لأصحاب المشاريع الاستفادة منها في الحصول على اشتراكات مجانية أو أرصدة استخدام أو خصومات على الخدمات اللازمة لتأسيس شركاتهم وتشغيلها. وتساعد هذه العروض على تخفيف التكاليف المرتبطة باستخدام البرمجيات التجارية، وتتيح للشركات تجربة أدوات متقدمة قبل التوسع في استخدامها. وتختلف شروط كل عرض ومدته وقيمته بحسب الجهة المقدمة له.$q$,$q$https://startups.aws.com/offers$q$,$q$https://startups.aws.com/offers$q$,array[$q$خصومات وخدمات مجانية$q$,$q$أدوات تطوير أعمال$q$,$q$تسويق$q$,$q$تطبيقات ذكاء اصطناعي$q$]::text[],array[$q$fund$q$,$q$prod$q$,$q$tech$q$,$q$market$q$]::text[],null,106),
  (107,$q$o15$q$,$q$المساعد التقني للشركات الناشئة – AWS Startup Advisor$q$,$q$خدمة ذكية تقدمها AWS لمساعدة مؤسسي الشركات الناشئة والمطورين على بناء منتجاتهم الرقمية وتشغيلها وتوسيع نطاقها. تستخدم الخدمة الذكاء الاصطناعي لتقديم توصيات تتناسب مع طبيعة المشروع ومرحلته، وتشمل تصميم البنية التقنية، واختيار الخدمات السحابية المناسبة، وتقدير التكاليف، وتحسين الأمان والأداء، ونقل التطبيقات إلى AWS. ويمكن استخدامها عبر الويب أو داخل بيئات التطوير مثل VS Code وKiro وCursor. وتساعد المبتكرين الذين يطورون تطبيقات رقمية أو حلول ذكاء اصطناعي على اتخاذ قرارات تقنية دون الحاجة إلى خبرة متقدمة في إدارة البنية السحابية. الخدمة نفسها متاحة دون رسوم إضافية، بينما تُحتسب تكاليف الموارد السحابية المستخدمة.$q$,$q$https://aws.amazon.com/aws-startups/advisor/$q$,$q$https://aws.amazon.com/aws-startups/advisor/$q$,array[$q$إرشاد تقني بالذكاء الاصطناعي$q$,$q$تصميم البنية السحابية$q$,$q$تحسين التكاليف$q$]::text[],array[$q$mentor$q$,$q$tech$q$]::text[],null,107),
  (108,$q$o15$q$,$q$برنامج اعتمادات Kiro للشركات الناشئة – Kiro Startup Credits Program$q$,$q$برنامج مخصص للشركات الناشئة المؤهلة للاستفادة من بيئة تطوير Kiro، التي تستخدم تقنيات الذكاء الاصطناعي للمساعدة في تصميم التطبيقات وكتابة التعليمات البرمجية واختبارها وتحسينها. يتيح البرنامج للشركات المؤهلة إمكانية الحصول على اشتراك في Kiro Pro+ لمدة تصل إلى سنة، وفق فئات الدعم المعتمدة. وتساعد الأداة الفرق التقنية الصغيرة على تحويل متطلبات المنتج إلى خطط تنفيذية، وتطوير البرمجيات بصورة أكثر تنظيمًا، وتسريع بناء النماذج الأولية والتطبيقات. ويستهدف البرنامج الشركات المدعومة برأس المال الجريء من المراحل المبكرة وحتى الجولة A، مع شروط أهلية تتعلق بالاستفادة السابقة من اعتمادات AWS Activate.$q$,$q$https://aws.amazon.com/aws-startups/learn/power-your-startup-with-1-year-of-kiro-pro-plus-now-available-through-aws-startups$q$,$q$https://aws.amazon.com/aws-startups/learn/power-your-startup-with-1-year-of-kiro-pro-plus-now-available-through-aws-startups$q$,array[$q$أدوات تطوير برمجيات$q$,$q$اعتمادات استخدام$q$,$q$برمجة بمساعدة الذكاء الاصطناعي$q$]::text[],array[$q$fund$q$,$q$tech$q$]::text[],null,108),
  (109,$q$o15$q$,$q$الدعم التقني للشركات الناشئة – AWS Support for Startups$q$,$q$خدمة دعم متخصصة للشركات الناشئة التي تعتمد على AWS في تطوير منتجاتها وتشغيلها. تتيح الاستفادة من الخبرات الهندسية والأدوات التقنية لمساعدة الشركات على معالجة مشكلات البنية السحابية، وتحسين موثوقية التطبيقات وأدائها، ومراقبة التكاليف، ومعالجة التحديات الأمنية والتشغيلية. وتشمل الخيارات المتاحة مستويات دعم مختلفة بحسب احتياجات المشروع، وقد توفر إمكانية التواصل مع مهندسي AWS على مدار الساعة للحالات التشغيلية الحرجة وفق خطة الدعم المختارة. ويمكن للشركات الناشئة الاستفادة من هذه الخدمات عند الانتقال من النموذج الأولي إلى التشغيل التجاري أو التوسع في عدد المستخدمين، مع مراعاة أن خطط الدعم المتقدمة قد تتطلب رسومًا إضافية.$q$,$q$https://aws.amazon.com/premiumsupport/startups/$q$,$q$https://aws.amazon.com/premiumsupport/startups/$q$,array[$q$استشارات تقنية$q$,$q$معالجة المشكلات$q$,$q$أمن المعلومات$q$,$q$تحسين الأداء$q$]::text[],array[$q$mentor$q$,$q$tech$q$]::text[],null,109),
  (110,$q$o15$q$,$q$سوق AWS للحلول البرمجية – AWS Marketplace$q$,$q$سوق رقمي يتيح للشركات التقنية ومطوري البرمجيات عرض منتجاتهم وخدماتهم أمام عملاء AWS من الشركات والمؤسسات حول العالم. ويمكن للشركات الناشئة نشر حلولها بصيغ متعددة، تشمل البرمجيات المقدمة كخدمة (SaaS)، والتطبيقات السحابية، والحاويات البرمجية، والمنتجات القائمة على البيانات. ويوفر السوق آليات لإدارة الاشتراكات والمدفوعات والفوترة، وخيارات لتحديد الأسعار وإعداد العروض الخاصة للعملاء. ويساعد ذلك الشركات على تقليل بعض التحديات المرتبطة بتوزيع البرمجيات والبيع المؤسسي، وتوسيع نطاق الوصول إلى العملاء خارج أسواقها المحلية. وتتطلب الاستفادة التسجيل كبائع واستيفاء متطلبات نشر المنتجات في السوق.$q$,$q$https://aws.amazon.com/partners/marketplace/$q$,$q$https://aws.amazon.com/partners/marketplace/$q$,array[$q$تسويق المنتجات$q$,$q$التجارة الرقمية$q$,$q$الوصول إلى العملاء الدوليين$q$]::text[],array[$q$prod$q$,$q$tech$q$,$q$market$q$]::text[],null,110),
  (111,$q$o15$q$,$q$برنامج تسريع موردي البرمجيات المستقلين – AWS ISV Accelerate$q$,$q$برنامج عالمي مخصص للشركات التي تطور وتبيع حلولًا برمجية تعمل على AWS أو تتكامل معها، ويهدف إلى مساعدتها على زيادة مبيعاتها من خلال التعاون مع فرق المبيعات والشركاء في AWS. يتيح البرنامج للشركات المؤهلة الاستفادة من أدوات التسويق والبيع المشترك، والتدريب التجاري، والتعريف بحلولها لدى مديري حسابات AWS والعملاء المحتملين. ويمكن للشركات الناشئة التي تمتلك منتجات برمجية تجارية جاهزة الاستفادة منه بعد الوصول إلى مستوى مناسب من النضج التجاري. ويشترط البرنامج الانضمام إلى شبكة شركاء AWS، وإدراج منتج في AWS Marketplace، وتحقيق متطلبات أخرى تتعلق بالمبيعات والشراكات والجاهزية التجارية.$q$,$q$https://aws.amazon.com/partners/programs/isv-accelerate/$q$,$q$https://aws.amazon.com/partners/programs/isv-accelerate/$q$,array[$q$تسويق مشترك$q$,$q$تطوير مبيعات$q$,$q$الوصول إلى العملاء المؤسسيين$q$]::text[],array[$q$incub$q$,$q$tech$q$,$q$market$q$]::text[],null,111),
  (112,$q$o15$q$,$q$البرنامج العالمي للشركات الناشئة – AWS Global Startup Program$q$,$q$برنامج مخصص للشركات التقنية الناشئة التي وصلت إلى مراحل متقدمة من النمو وترغب في توسيع حضورها التجاري من خلال شبكة AWS العالمية. يوفر البرنامج فرص التعاون مع فرق المبيعات والشركاء، والتطوير المشترك لاستراتيجيات التسويق والوصول إلى العملاء المؤسسيين. ويستهدف شركات البرمجيات التي تمتلك منتجات تجارية قائمة وعلاقات استثمارية وشراكات متقدمة. ومن متطلبات البرنامج الحصول على تمويل من الجولة الاستثمارية A على الأقل، والاشتراك في برنامج AWS ISV Accelerate، واستيفاء شروط تتعلق بالمنتج والمبيعات. ويمكن للشركات التقنية السعودية المؤهلة الاستفادة منه في توسيع نطاق تسويق منتجاتها وتعزيز حضورها في الأسواق الدولية.$q$,$q$https://aws.amazon.com/partners/programs/global-startup/$q$,$q$https://aws.amazon.com/partners/programs/global-startup/$q$,array[$q$شراكات تجارية$q$,$q$تسويق مشترك$q$,$q$توسع عالمي$q$]::text[],array[$q$market$q$]::text[],null,112),
  (113,$q$o15$q$,$q$منصة AWS Skill Builder$q$,$q$منصة تعليمية تقدمها AWS لتطوير المهارات التقنية في مجالات الحوسبة السحابية والذكاء الاصطناعي والأمن السيبراني وتحليل البيانات وتطوير البرمجيات. توفر المنصة أكثر من ألف مورد تعليمي مجاني، تشمل دورات ذاتية التعلم ومسارات تدريبية متخصصة تناسب المبتدئين والمتخصصين. كما تتيح اشتراكات مدفوعة للوصول إلى مختبرات وتجارب تدريبية متقدمة واختبارات تحضيرية للشهادات المهنية. ويمكن للمبتكرين وأصحاب الشركات الناشئة الاستفادة منها لتطوير مهاراتهم التقنية، وتأهيل أعضاء فرقهم على استخدام خدمات AWS، وتعلم أساليب بناء التطبيقات وإدارتها. وتساعد المنصة على تقليل الحاجة إلى التدريب الخارجي خلال المراحل الأولى من تطوير المشاريع التقنية.$q$,$q$https://aws.amazon.com/training/digital/$q$,$q$https://aws.amazon.com/training/digital/$q$,array[$q$تدريب سحابي$q$,$q$ذكاء اصطناعي$q$,$q$شهادات مهنية$q$,$q$تطوير مهارات$q$]::text[],array[$q$train$q$,$q$tech$q$]::text[],null,113),
  (114,$q$o15$q$,$q$برنامج AWS Educate$q$,$q$برنامج تعليمي مجاني يستهدف الطلاب والمبتدئين والمهتمين باكتساب المهارات التقنية في الحوسبة السحابية والذكاء الاصطناعي. يتيح للمشاركين مسارات تعليمية ذاتية التعلم وتجارب عملية باستخدام خدمات AWS، دون الحاجة إلى بطاقة ائتمانية عند التسجيل. وتشمل الموضوعات التخزين السحابي، وإدارة الخوادم الافتراضية، والشبكات، وقواعد البيانات، والعمليات السحابية. ويمكن للمشاركين الحصول على شارات رقمية تثبت إكمالهم لمسارات تدريبية محددة. ويعد البرنامج مناسبًا للطلاب والمبتكرين الذين يرغبون في التعرف على تقنيات تطوير التطبيقات والخدمات الرقمية، واكتساب المهارات الأساسية اللازمة لبناء نماذج أولية، قبل الانتقال إلى استخدام الخدمات السحابية في مشاريع تجارية.$q$,$q$https://aws.amazon.com/education/awseducate/$q$,$q$https://aws.amazon.com/education/awseducate/$q$,array[$q$تدريب مجاني$q$,$q$مختبرات عملية$q$,$q$مهارات الحوسبة السحابية$q$]::text[],array[$q$train$q$,$q$tech$q$,$q$space$q$]::text[],null,114),
  (115,$q$o15$q$,$q$برنامج بيئة الابتكار التجريبية – AWS Innovation Sandbox$q$,$q$يوفر برنامج AWS Innovation Sandbox بيئة سحابية آمنة ومخصصة للتجارب التقنية وتطوير الحلول المبتكرة واختبار النماذج الأولية قبل الانتقال إلى التشغيل التجاري. يتيح البرنامج للفرق التقنية والمطورين تجربة خدمات AWS في بيئات معزولة، مع أدوات للتحكم في التكاليف وإدارة الصلاحيات ومراقبة الاستخدام. ويساعد المبتكرين والشركات التقنية على اختبار الأفكار والتحقق من جدواها الفنية وتطوير التطبيقات دون التأثير في الأنظمة التشغيلية القائمة. كما توفر AWS لشركائها المؤهلين ضمن شبكة AWS Partner Network اعتمادات سحابية من خلال برنامج APN Innovation Sandbox Credits، للمساهمة في تغطية تكاليف تطوير الحلول والمنتجات القائمة على خدمات AWS.$q$,$q$https://docs.aws.amazon.com/solutions/innovation-sandbox-on-aws/$q$,$q$https://docs.aws.amazon.com/solutions/innovation-sandbox-on-aws/$q$,array[$q$بيئة تجريبية سحابية$q$,$q$تطوير النماذج الأولية$q$,$q$اختبار الحلول التقنية$q$,$q$اعتمادات سحابية$q$]::text[],array[$q$fund$q$,$q$prod$q$,$q$tech$q$]::text[],null,115),
  (116,$q$o16$q$,$q$برنامج تطوير النموذج الأولي لتقنيات الطاقة المتجددة$q$,$q$برنامج يستهدف تطوير التقنيات المبتكرة في مجالات الطاقة المتجددة من خلال تحويل الأفكار والنتائج البحثية الواعدة إلى نماذج أولية قابلة للاختبار. يتيح البرنامج مسارًا للتعاون بين الجامعات والمراكز البحثية وشركات القطاع الخاص، بهدف إثبات الجدوى الفنية للتقنيات وتقليل المخاطر المرتبطة بتطويرها قبل الانتقال إلى التطبيق التجاري. ويشمل نطاق المبادرة تقنيات الطاقة الشمسية وطاقة الرياح وتخزين الطاقة وتحلية المياه والتطبيقات الصناعية للطاقة المتجددة. ويمكن للباحثين والمبتكرين الذين يمتلكون تقنيات في مراحل التطوير المبكرة الاستفادة من هذا المسار لاستكمال التجارب وتقييم الأداء وتحديد متطلبات تطوير المنتج بما يتناسب مع الظروف التشغيلية والبيئية في المملكة.$q$,$q$https://www.energy.gov.sa/ar/about/Pages/ProjectsInitiatives.aspx$q$,$q$https://www.energy.gov.sa/ar/about/Pages/ProjectsInitiatives.aspx$q$,array[$q$تطوير نماذج أولية$q$,$q$بحث وتطوير$q$,$q$تحقق فني$q$]::text[],array[$q$prod$q$,$q$ip$q$]::text[],null,116),
  (117,$q$o16$q$,$q$أطلس مصادر الطاقة المتجددة – Renewable Resource Atlas$q$,$q$منصة وطنية تقدمها مدينة الملك عبدالله للطاقة الذرية والمتجددة، وتتيح للمطورين والباحثين والشركات الاطلاع على بيانات مصادر الطاقة الشمسية وطاقة الرياح في مناطق المملكة. تتضمن المنصة قياسات فعلية من محطات الرصد، إلى جانب بيانات تاريخية ونموذجية مستمدة من الأقمار الصناعية، بما يساعد على تقييم الموارد الطبيعية وتحديد المواقع المناسبة لمشاريع الطاقة المتجددة. ويمكن للمبتكرين الاستفادة منها في إعداد دراسات الجدوى، وتصميم أنظمة الطاقة، وتطوير الحلول التقنية التي تعتمد على الظروف المناخية المحلية. كما تتيح طلب مجموعات بيانات محددة لدعم الدراسات البحثية والمشاريع التجارية، وفق الإجراءات المعتمدة.$q$,$q$https://reatlas.energy.gov.sa/ar$q$,$q$https://reatlas.energy.gov.sa/ar$q$,array[$q$بيانات الطاقة الشمسية والرياح$q$,$q$دراسات جدوى$q$,$q$تطوير مشاريع الطاقة$q$]::text[],array[$q$prod$q$,$q$tech$q$,$q$ip$q$]::text[],null,117),
  (118,$q$o16$q$,$q$البيانات المفتوحة للطاقة الذرية والمتجددة$q$,$q$خدمة تتيح للمبتكرين والباحثين ومطوري التطبيقات الوصول إلى مجموعات من البيانات المنشورة من قبل المدينة، بما في ذلك بيانات محطات رصد الطاقة الشمسية والرياح، وبيانات منصة أطلس. وتوفر بعض البيانات من خلال واجهات برمجية (API)، مما يساعد على دمجها في التطبيقات الرقمية ولوحات المعلومات وأدوات التحليل. ويمكن لأصحاب المشاريع الاستفادة من هذه المصادر في تطوير حلول للتنبؤ بإنتاج الطاقة، وتحليل الموارد المتجددة، ودعم تخطيط أنظمة الطاقة. كما توفر البيانات مرجعًا للدراسات التقنية والاقتصادية، مع ضرورة مراعاة تاريخ تحديث البيانات ومستوى دقتها وشروط إعادة استخدامها والإشارة إلى مصدرها.$q$,$q$https://www.energy.gov.sa/ar/e-services/DataManagement/opendata/Pages/default.aspx$q$,$q$https://www.energy.gov.sa/ar/e-services/DataManagement/opendata/Pages/default.aspx$q$,array[$q$بيانات مفتوحة$q$,$q$تحليل تقني$q$,$q$تطوير تطبيقات وحلول رقمية$q$]::text[],array[$q$prod$q$,$q$tech$q$]::text[],null,118),
  (119,$q$o16$q$,$q$مبادرة البرامج التدريبية المتخصصة في تقنية المعلومات والاتصالات بقطاع الطاقة$q$,$q$مبادرة تدريبية أطلقتها المدينة في مارس 2026، بالتعاون مع الأكاديمية الوطنية لتقنية المعلومات، وتضم 18 برنامجًا متخصصًا في مجالات الذكاء الاصطناعي وعلوم البيانات والتحول الرقمي وتقنيات الطاقة المتجددة. تهدف المبادرة إلى تطوير القدرات التقنية للكفاءات الوطنية ورفع جاهزيتها للعمل في قطاع الطاقة، بما يدعم الابتكار وتطوير التطبيقات الرقمية. وتستهدف منسوبي منظومة الطاقة والعاملين في القطاع الخاص ذي العلاقة، إضافة إلى رواد الأعمال المشاركين في مسرعة «طاقتك». وتنفذ البرامج في مدينتي الرياض والدمام خلال الفترة من مارس إلى نوفمبر 2026، وفق جداول التدريب ومتطلبات المشاركة.$q$,$q$https://www.energy.gov.sa/ar/mediacenter/news/Pages/training-programs-with-the-national-academy-of-information-technology.aspx$q$,$q$https://www.energy.gov.sa/ar/mediacenter/news/Pages/training-programs-with-the-national-academy-of-information-technology.aspx$q$,array[$q$تدريب تخصصي$q$,$q$ذكاء اصطناعي$q$,$q$تحول رقمي$q$]::text[],array[$q$train$q$,$q$tech$q$]::text[],null,119),
  (120,$q$o16$q$,$q$معرض مشكاة التفاعلي – Mishkat Interactive Center$q$,$q$مركز تعليمي وتفاعلي أنشأته مدينة الملك عبدالله للطاقة الذرية والمتجددة لتعزيز المعرفة العلمية لدى الطلاب والناشئة والمجتمع في مجالات الطاقة والاستدامة. يقدم المركز معروضات وتجارب تفاعلية وبرامج تعليمية وعروضًا علمية تساعد الزوار على فهم مصادر الطاقة وطرق توليدها ونقلها واستخدامها. ويستهدف تنمية الاهتمام بالعلوم والهندسة وتشجيع الأجيال الجديدة على التفكير في الحلول المبتكرة لتحديات الطاقة. ويمكن للطلاب والفرق الابتكارية الاستفادة من الزيارات والأنشطة التعليمية في تنمية معارفهم واستلهام أفكار لمشاريع جديدة. وهو مركز للتوعية والتعليم، وليس حاضنة تجارية لتمويل المشاريع الناشئة.$q$,$q$https://www.energy.gov.sa/ar/e-services/Pages/Mishkat.aspx$q$,$q$https://www.energy.gov.sa/ar/e-services/Pages/Mishkat.aspx$q$,array[$q$تعليم تفاعلي$q$,$q$تنمية الاهتمام العلمي$q$,$q$توعية بتقنيات الطاقة$q$]::text[],array[$q$train$q$]::text[],null,120);
